  1	//! The stack routine (PLAN.md A1, D13): start, attach to, and stop the compose
  2	//! project in the profile's checkout. `iii ps --json` is the source of truth.
  3	
  4	use std::path::PathBuf;
  5	use std::time::Duration;
  6	
  7	use bastion_protocol::{StackState, StackStatus, StartRefused};
  8	use serde::Deserialize;
  9	
 10	use crate::doctor::{self, COMPOSE_FILE};
 11	use crate::engine::Engine;
 12	use crate::machine::Machine;
 13	
 14	/// How long a started daemon has to show up in `iii ps`.
 15	const START_WAIT: Duration = Duration::from_secs(10);
 16	const START_POLL: Duration = Duration::from_millis(250);
 17	
 18	/// Where this profile's stack lives.
 19	#[derive(Clone, Debug)]
 20	pub struct Stack {
 21	    pub checkout: PathBuf,
 22	    /// The engine port the profile points at.
 23	    pub port: u16,
 24	    pub log: PathBuf,
 25	}
 26	
 27	#[derive(Deserialize)]
 28	struct Process {
 29	    pid: u32,
 30	    kind: String,
 31	    #[serde(default)]
 32	    ports: Vec<u16>,
 33	    compose_file: Option<String>,
 34	}
 35	
 36	impl Stack {
 37	    pub fn compose_file(&self) -> PathBuf {
 38	        self.checkout.join(COMPOSE_FILE)
 39	    }
 40	
 41	    pub fn status(&self, machine: &dyn Machine) -> Result<StackStatus, String> {
 42	        Ok(StackStatus {
 43	            state: self.state(machine)?,
 44	            compose_file: self.compose_file().display().to_string(),
 45	            log: self.log.display().to_string(),
 46	        })
 47	    }
 48	
 49	    fn state(&self, machine: &dyn Machine) -> Result<StackState, String> {
 50	        let out = machine.run("iii", &["ps", "--json"], None)?;
 51	        if !out.success {
 52	            return Err(format!("iii ps: {}", out.text.trim()));
 53	        }
 54	        let processes: Vec<Process> =
 55	            serde_json::from_str(&out.text).map_err(|e| format!("iii ps --json: {e}"))?;
 56	        let ours = self.compose_file().display().to_string();
 57	        if processes
 58	            .iter()
 59	            .any(|p| p.kind == "compose" && p.compose_file.as_deref() == Some(ours.as_str()))
 60	        {
 61	            return Ok(StackState::Running);
 62	        }
 63	        Ok(processes
 64	            .into_iter()
 65	            .find(|p| p.kind == "engine" && p.ports.contains(&self.port))
 66	            .map_or(StackState::Stopped, |p| StackState::Taken {
 67	                pid: p.pid,
 68	                compose_file: p.compose_file,
 69	            }))
 70	    }
 71	
 72	    /// Attach to a running stack, or run Doctor and start one.
 73	    pub async fn start(
 74	        &self,
 75	        machine: &dyn Machine,
 76	        engine: &dyn Engine,
 77	    ) -> Result<StackStatus, StartRefused> {
 78	        let failed = |message: String| StartRefused::Failed { message };
 79	        match self.state(machine).map_err(failed)? {
 80	            StackState::Running => return self.status(machine).map_err(failed),
 81	            StackState::Taken { pid, compose_file } => {
 82	                return Err(StartRefused::Taken { pid, compose_file });
 83	            }
 84	            StackState::Stopped => {}
 85	        }
 86	        let report = doctor::run(machine, engine, &self.checkout).await;
 87	        if !report.ready() {
 88	            return Err(StartRefused::Doctor { report });
 89	        }
 90	        let file = self.compose_file().display().to_string();
 91	        machine
 92	            .spawn(
 93	                "iii",
 94	                &["compose", "--up", "-f", &file],
 95	                &self.checkout,
 96	                &self.log,
 97	            )
 98	            .map_err(failed)?;
 99	        let mut waited = Duration::ZERO;
100	        while waited < START_WAIT {
101	            if self.state(machine).map_err(failed)? == StackState::Running {
102	                return self.status(machine).map_err(failed);
103	            }
104	            tokio::time::sleep(START_POLL).await;
105	            waited += START_POLL;
106	        }
107	        Err(failed(format!(
108	            "the compose daemon did not appear within {}s; see {}",
109	            START_WAIT.as_secs(),
110	            self.log.display()
111	        )))
112	    }
113	
114	    pub fn stop(&self, machine: &dyn Machine) -> Result<StackStatus, String> {
115	        let file = self.compose_file().display().to_string();
116	        let out = machine.run("iii", &["kill", "--compose", &file], Some(&self.checkout))?;
117	        if !out.success {
118	            return Err(format!("iii kill: {}", out.text.trim()));
119	        }
120	        self.status(machine)
121	    }
122	}
123	
124	/// The port in an engine URL such as `ws://127.0.0.1:49160`.
125	pub fn port(url: &str) -> Option<u16> {
126	    url.rsplit(':').next()?.trim_end_matches('/').parse().ok()
127	}
