129	#[cfg(test)]
130	mod tests {
131	    use super::*;
132	    use crate::engine::fake::FakeEngine;
133	    use crate::machine::fake::FakeMachine;
134	    use bastion_protocol::Link;
135	
136	    const COMPOSE: &str = "containers:\n  a:\n    worker: package://a\n    version: \"1.2.3\"\n";
137	
138	    fn stack() -> Stack {
139	        Stack {
140	            checkout: "/repo".into(),
141	            port: 49160,
142	            log: "/logs/compose.log".into(),
143	        }
144	    }
145	
146	    fn ps(rows: &str) -> String {
147	        format!("[{rows}]")
148	    }
149	
150	    const OURS: &str =
151	        r#"{"pid":7,"kind":"compose","ports":[49160],"compose_file":"/repo/worker-compose.yaml"}"#;
152	    const OTHER: &str = r#"{"pid":9,"kind":"engine","ports":[49160],"compose_file":"/elsewhere/worker-compose.yaml"}"#;
153	
154	    fn ready_machine() -> FakeMachine {
155	        FakeMachine::new()
156	            .run_ok("iii", "0.25.0")
157	            .run_ok("gh", "ok")
158	            .file("/repo/worker-compose.yaml", COMPOSE)
159	    }
160	
161	    fn start(machine: &FakeMachine) -> Result<StackStatus, StartRefused> {
162	        let engine = FakeEngine::new(Link::Down);
163	        crate::rt::block_on(stack().start(machine, &engine))
164	    }
165	
166	    #[test]
167	    fn port_comes_from_the_engine_url() {
168	        assert_eq!(port("ws://127.0.0.1:49160"), Some(49160));
169	        assert_eq!(port("ws://box"), None);
170	    }
171	
172	    #[test]
173	    fn a_running_stack_is_attached_not_started_twice() {
174	        let machine = FakeMachine::new().run_ok("iii", &ps(OURS));
175	        assert_eq!(start(&machine).unwrap().state, StackState::Running);
176	        assert!(!machine.called("spawn"));
177	    }
178	
179	    #[test]
180	    fn a_port_held_by_another_project_is_refused_with_its_owner() {
181	        let machine = FakeMachine::new().run_ok("iii", &ps(OTHER));
182	        let refused = start(&machine).unwrap_err();
183	        assert_eq!(
184	            refused,
185	            StartRefused::Taken {
186	                pid: 9,
187	                compose_file: Some("/elsewhere/worker-compose.yaml".into())
188	            }
189	        );
190	        assert!(!machine.called("spawn"));
191	    }
192	
193	    #[test]
194	    fn a_failed_doctor_stops_the_start() {
195	        // `iii ps` answers, then `iii --version` reports the wrong iii.
196	        let machine = FakeMachine::new()
197	            .run_ok("iii", &ps(""))
198	            .run_ok("iii", "0.23.0")
199	            .run_ok("gh", "ok")
200	            .file("/repo/worker-compose.yaml", COMPOSE);
201	        assert!(matches!(start(&machine), Err(StartRefused::Doctor { .. })));
202	        assert!(!machine.called("spawn"));
203	    }
204	
205	    #[test]
206	    fn a_stopped_stack_starts_in_the_checkout() {
207	        // `iii ps` (stopped), `iii --version`, then `iii ps` (running) from then on.
208	        let machine = FakeMachine::new()
209	            .run_ok("iii", &ps(""))
210	            .run_ok("iii", "0.25.0")
211	            .run_ok("iii", &ps(OURS))
212	            .run_ok("gh", "ok")
213	            .file("/repo/worker-compose.yaml", COMPOSE);
214	        assert_eq!(start(&machine).unwrap().state, StackState::Running);
215	        assert!(machine.called("spawn iii compose --up -f /repo/worker-compose.yaml"));
216	    }
217	
218	    #[test]
219	    fn stop_kills_this_compose_project_only() {
220	        let machine = ready_machine();
221	        let _ = stack().stop(&machine);
222	        assert!(machine.called("iii kill --compose /repo/worker-compose.yaml"));
223	    }
224	}
