226	/// Attach to this machine's running stack: `cargo test -p bastion -- --ignored --nocapture live_attach`.
227	#[cfg(test)]
228	mod live {
229	    use super::*;
230	    use crate::engine::IiiEngine;
231	    use crate::machine::ThisMachine;
232	
233	    #[test]
234	    #[ignore = "needs this machine's stack"]
235	    fn live_attach() {
236	        let stack = Stack {
237	            checkout: std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
238	                .join("..")
239	                .canonicalize()
240	                .unwrap(),
241	            port: 49160,
242	            log: std::env::temp_dir().join("bastion-live-compose.log"),
243	        };
244	        println!("status: {:?}", stack.status(&ThisMachine));
245	        let engine = IiiEngine::connect("ws://127.0.0.1:49160");
246	        let started = crate::rt::block_on(stack.start(&ThisMachine, &engine));
247	        println!("start: {started:?}");
248	        assert_eq!(started.unwrap().state, StackState::Running);
249	    }
250	}
  1	//! Commands and events about the engine link.
  2	
  3	use std::sync::Arc;
  4	use std::time::Duration;
  5	
  6	use bastion_protocol::{Change, EngineStatus, Link};
  7	use serde_json::json;
  8	
  9	use crate::engine::{DEFAULT_NAMESPACE, Engine};
 10	use crate::events::Bus;
 11	
 12	/// How often the watcher reads the link. The SDK offers no listener for it.
 13	// ponytail: a local read every half second; switch to a listener if iii-sdk adds one.
 14	const LINK_POLL: Duration = Duration::from_millis(500);
 15	
 16	pub async fn status(engine: &dyn Engine) -> EngineStatus {
 17	    let link = engine.link();
 18	    let functions = match link {
 19	        Link::Up => engine
 20	            .call(DEFAULT_NAMESPACE, "engine::functions::list", json!({}))
 21	            .await
 22	            .ok()
 23	            .and_then(|out| out["functions"].as_array().map(Vec::len)),
 24	        _ => None,
 25	    };
 26	    EngineStatus {
 27	        url: engine.url().into(),
 28	        link,
 29	        functions,
 30	    }
 31	}
 32	
 33	pub async fn engine_status(engine: &Arc<dyn Engine>) -> Result<EngineStatus, ()> {
 34	    Ok(status(engine.as_ref()).await)
 35	}
 36	
 37	/// Publish the engine status each time the link changes.
 38	pub fn watch(events: Arc<Bus>, engine: Arc<dyn Engine>) {
 39	    crate::rt::spawn(async move {
 40	        let mut last = None;
 41	        loop {
 42	            let link = engine.link();
 43	            if last != Some(link) {
 44	                last = Some(link);
 45	                let status = status(engine.as_ref()).await;
 46	                events.publish(Change::Engine { status });
 47	            }
 48	            tokio::time::sleep(LINK_POLL).await;
 49	        }
 50	    });
 51	}
 52	
 53	#[cfg(test)]
 54	mod tests {
 55	    use super::*;
 56	    use crate::engine::fake::FakeEngine;
 57	
 58	    #[test]
 59	    fn up_link_counts_the_engine_functions() {
 60	        let engine = FakeEngine::new(Link::Up).answer(
 61	            "engine::functions::list",
 62	            Ok(json!({ "functions": [{}, {}, {}] })),
 63	        );
 64	        let status = crate::rt::block_on(status(&engine));
 65	        assert_eq!(
 66	            status,
 67	            EngineStatus {
 68	                url: "ws://fake".into(),
 69	                link: Link::Up,
 70	                functions: Some(3)
 71	            }
 72	        );
 73	        assert_eq!(engine.calls.lock().unwrap()[0].0, DEFAULT_NAMESPACE);
 74	    }
 75	
 76	    #[test]
 77	    fn down_link_makes_no_call() {
 78	        let engine = FakeEngine::new(Link::Down);
 79	        let status = crate::rt::block_on(status(&engine));
 80	        assert_eq!(status.functions, None);
 81	        assert!(engine.calls.lock().unwrap().is_empty());
 82	    }
 83	
 84	    #[test]
 85	    fn a_failed_call_still_reports_the_link() {
 86	        let engine =
 87	            FakeEngine::new(Link::Up).answer("engine::functions::list", Err("timeout".into()));
 88	        let status = crate::rt::block_on(status(&engine));
 89	        assert_eq!((status.link, status.functions), (Link::Up, None));
 90	    }
 91	}

