  1	//! The audit writer (PLAN.md D21): the one writer of the chain. Records
  2	//! queue on a channel and one task appends them in order, each under a time
  3	//! limit, so a stalled store shows as pending records and an error instead
  4	//! of a stalled turn. The chain is keyed with a secret kept in the Keychain,
  5	//! not in the database.
  6	
  7	use std::sync::atomic::{AtomicU64, Ordering};
  8	use std::sync::{Arc, Mutex};
  9	use std::time::Duration;
 10	
 11	use bastion_core::audit::{self, Entry, Record};
 12	use tokio::sync::mpsc;
 13	
 14	use crate::factory::now;
 15	use crate::machine::Machine;
 16	use crate::store::Store;
 17	
 18	/// How long one append may take before it counts as stalled.
 19	pub const WRITE_LIMIT: Duration = Duration::from_secs(5);
 20	const SERVICE: &str = "bastion-audit";
 21	
 22	pub struct AuditLog {
 23	    store: Arc<dyn Store>,
 24	    key: Vec<u8>,
 25	    records: mpsc::UnboundedSender<Record>,
 26	    pending: Arc<AtomicU64>,
 27	    last_error: Arc<Mutex<Option<String>>>,
 28	}
 29	
 30	/// The chain as read, and the first entry that breaks it, if one does.
 31	pub struct Read {
 32	    pub chain: Vec<Entry>,
 33	    pub broken_at: Option<u64>,
 34	}
 35	
 36	impl AuditLog {
 37	    pub fn start(store: Arc<dyn Store>, key: Vec<u8>, limit: Duration) -> Arc<Self> {
 38	        let (records, mut queue) = mpsc::unbounded_channel::<Record>();
 39	        let log = Arc::new(Self {
 40	            store: store.clone(),
 41	            key: key.clone(),
 42	            records,
 43	            pending: Arc::new(AtomicU64::new(0)),
 44	            last_error: Arc::new(Mutex::new(None)),
 45	        });
 46	        let (pending, last_error) = (log.pending.clone(), log.last_error.clone());
 47	        crate::rt::spawn(async move {
 48	            while let Some(what) = queue.recv().await {
 49	                let written = tokio::time::timeout(limit, append(&*store, &key, what)).await;
 50	                let error = match written {
 51	                    Ok(Ok(())) => None,
 52	                    Ok(Err(e)) => Some(format!("the audit record was not written: {e}")),
 53	                    Err(_) => Some(format!(
 54	                        "an audit write took longer than {}s",
 55	                        limit.as_secs()
 56	                    )),
 57	                };
 58	                if let Some(e) = &error {
 59	                    eprintln!("{e}");
 60	                }
 61	                *last_error.lock().unwrap() = error;
 62	                pending.fetch_sub(1, Ordering::Relaxed);
 63	            }
 64	        });
 65	        log
 66	    }
 67	
 68	    /// Queue a record. It never waits on the store.
 69	    pub fn note(&self, record: Record) {
 70	        self.pending.fetch_add(1, Ordering::Relaxed);
 71	        if self.records.send(record).is_err() {
 72	            self.pending.fetch_sub(1, Ordering::Relaxed);
 73	        }
 74	    }
 75	
 76	    /// Records queued and not yet written, and the last write's error.
 77	    pub fn status(&self) -> (u64, Option<String>) {
 78	        (
 79	            self.pending.load(Ordering::Relaxed),
 80	            self.last_error.lock().unwrap().clone(),
 81	        )
 82	    }
 83	
 84	    /// The whole chain, verified under the key as it is read.
 85	    pub async fn read(&self) -> Result<Read, String> {
 86	        let chain = self.store.audit().await?;
 87	        let broken_at = audit::verify(&chain, &self.key).err();
 88	        Ok(Read { chain, broken_at })
 89	    }
 90	}
 91	
 92	/// Append the entry after the last one in the store.
 93	// ponytail: reads the whole chain to find its tail; read only the last row when the chain grows large.
 94	async fn append(store: &dyn Store, key: &[u8], what: Record) -> Result<(), String> {
 95	    let chain = store.audit().await?;
 96	    let entry = audit::append(chain.last(), now(), what, key);
 97	    store.append_audit(&entry).await
 98	}
 99	
100	/// The chain's key from the macOS Keychain, made on first use.
101	// ponytail: `security -w` takes the new key as an argument, so it shows in the process list for a moment; use the Keychain API if that matters.
102	pub fn key(machine: &dyn Machine) -> Result<Vec<u8>, String> {
103	    let account = ["-s", SERVICE, "-a", "bastion"];
104	    let found = machine.run(
105	        "security",
106	        &[&["find-generic-password"][..], &account, &["-w"]].concat(),
107	        None,
108	    )?;
109	    if found.success {
110	        return unhex(found.text.trim());
111	    }
112	    let key: Vec<u8> = [uuid::Uuid::new_v4(), uuid::Uuid::new_v4()]
113	        .iter()
114	        .flat_map(|u| *u.as_bytes())
115	        .collect();
116	    let hex: String = key.iter().map(|b| format!("{b:02x}")).collect();
117	    let made = machine.run(
118	        "security",
119	        &[&["add-generic-password"][..], &account, &["-w", &hex]].concat(),
120	        None,
121	    )?;
122	    if !made.success {
123	        return Err(format!(
124	            "the Keychain refused the audit key: {}",
125	            made.text.trim()
126	        ));
127	    }
128	    Ok(key)
129	}
130	
131	fn unhex(text: &str) -> Result<Vec<u8>, String> {
132	    let bad = || "the audit key in the Keychain is not hex".to_string();
133	    if text.len() != 64 {
134	        return Err(bad());
135	    }
136	    (0..text.len())
137	        .step_by(2)
138	        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).map_err(|_| bad()))
139	        .collect()
140	}
141	
142	#[cfg(test)]
143	mod tests {
144	    use super::*;
145	    use crate::machine::fake::FakeMachine;
146	    use crate::store::fake::FakeStore;
147	
148	    fn record(detail: &str) -> Record {
149	        Record {
150	            kind: "gate".into(),
151	            subject: "j1".into(),
152	            detail: detail.into(),
153	        }
154	    }
155	
156	    fn settle() {
157	        std::thread::sleep(Duration::from_millis(100));
158	    }
159	
160	    #[test]
161	    fn records_chain_in_order_under_the_key() {
162	        let store = Arc::new(FakeStore::default());
163	        let log = AuditLog::start(store.clone(), b"k".to_vec(), WRITE_LIMIT);
164	        log.note(record("one"));
165	        log.note(record("two"));
166	        settle();
167	        let read = crate::rt::block_on(log.read()).unwrap();
168	        assert_eq!(read.chain.len(), 2);
169	        assert_eq!(read.broken_at, None);
170	        assert_eq!(audit::verify(&read.chain, b"another key"), Err(1));
171	        assert_eq!(log.status(), (0, None));
172	    }
173	
174	    #[test]
175	    fn a_stalled_store_shows_as_pending_and_then_an_error() {
176	        let store = Arc::new(FakeStore::default());
177	        *store.stall_audit.lock().unwrap() = true;
178	        let log = AuditLog::start(store, b"k".to_vec(), Duration::from_millis(50));
179	        let started = std::time::Instant::now();
180	        log.note(record("one"));
181	        log.note(record("two"));
182	        assert!(
183	            started.elapsed() < Duration::from_millis(10),
184	            "noting must not wait"
185	        );
186	        assert_eq!(log.status().0, 2);
187	        std::thread::sleep(Duration::from_millis(250));
188	        let (pending, error) = log.status();
189	        assert_eq!(pending, 0);
190	        assert!(error.unwrap().contains("longer than"));
191	    }
192	
193	    #[test]
194	    fn the_key_is_read_from_the_keychain_or_made() {
195	        let hex = "ab".repeat(32);
196	        let found = FakeMachine::new().run_ok("security", &hex);
197	        assert_eq!(key(&found).unwrap(), vec![0xab; 32]);
198	        let refused = FakeMachine::new().run_fails("security", "no keychain");
199	        assert!(key(&refused).is_err());
200	    }
201	}
  1	//! The runtime the server's tasks run on. One process-wide `tokio` runtime,
  2	//! made on first use, so a task can start from any thread, including the
  3	//! engine's callbacks.
  4	
  5	use std::future::Future;
  6	use std::sync::OnceLock;
  7	
  8	use tokio::runtime::{Handle, Runtime};
  9	use tokio::task::JoinHandle;
 10	
 11	fn handle() -> &'static Handle {
 12	    static RT: OnceLock<Runtime> = OnceLock::new();
 13	    RT.get_or_init(|| Runtime::new().expect("a tokio runtime"))
 14	        .handle()
 15	}
 16	
 17	pub fn spawn<F>(task: F) -> JoinHandle<F::Output>
 18	where
 19	    F: Future + Send + 'static,
 20	    F::Output: Send + 'static,
 21	{
 22	    handle().spawn(task)
 23	}
 24	
 25	/// Run a future to its end from outside the runtime, as a test does.
 26	pub fn block_on<F: Future>(task: F) -> F::Output {
 27	    handle().block_on(task)
 28	}
  1	//! The Engine seam (PLAN.md §6.2). This module is the only code in the app that
  2	//! imports `iii-sdk` (D19). Everything else holds an `Arc<dyn Engine>`.
  3	
  4	#[cfg(any(test, feature = "fakes"))]
  5	pub mod fake;
  6	mod iii;
  7	
  8	use std::future::Future;
  9	use std::pin::Pin;
 10	use std::sync::Arc;
 11	
 12	use bastion_protocol::Link;
 13	use serde_json::Value;
 14	
 15	pub use iii::IiiEngine;
 16	
 17	/// The namespace the engine registers its own functions in, such as `engine::*`.
 18	pub const DEFAULT_NAMESPACE: &str = "default";
 19	
 20	pub type Call<'a> = Pin<Box<dyn Future<Output = Result<Value, String>> + Send + 'a>>;
 21	
 22	/// Run on each push from the engine. It must return quickly.
 23	pub type OnPush = Arc<dyn Fn() + Send + Sync>;
 24	
 25	/// Handle one trigger event and return the handler's answer (`{}` for a
 26	/// plain event, a decision for a hook). It must return quickly.
 27	pub type OnEvent = Arc<dyn Fn(Value) -> Value + Send + Sync>;
 28	
 29	pub type Bytes<'a> = Pin<Box<dyn Future<Output = Result<Vec<u8>, String>> + Send + 'a>>;
 30	
 31	/// How long a call waits by default. Slow calls, such as booting a VM, pass
 32	/// their own timeout to `call_for`.
 33	pub const CALL_TIMEOUT_MS: u64 = 5_000;
 34	
 35	pub trait Engine: Send + Sync {
 36	    /// The engine's address, as the profile gave it.
 37	    fn url(&self) -> &str;
 38	    /// The link as it is now. The SDK reconnects by itself.
 39	    fn link(&self) -> Link;
 40	    /// Call one function and wait for its answer, up to `CALL_TIMEOUT_MS`.
 41	    fn call<'a>(&'a self, namespace: &'a str, function_id: &'a str, payload: Value) -> Call<'a> {
 42	        self.call_for(namespace, function_id, payload, CALL_TIMEOUT_MS)
 43	    }
 44	    fn call_for<'a>(
 45	        &'a self,
 46	        namespace: &'a str,
 47	        function_id: &'a str,
 48	        payload: Value,
 49	        timeout_ms: u64,
 50	    ) -> Call<'a>;
 51	    /// Run `on_event` for each event of `trigger_type` that matches `config`.
 52	    /// Returns the binding's id for `unbind`.
 53	    fn bind(&self, trigger_type: &str, config: Value, on_event: OnEvent) -> Result<String, String>;
 54	    fn unbind(&self, id: &str);
 55	    /// Read every byte of a content channel, such as `sandbox::fs::read` returns.
 56	    fn read_channel(&self, content: Value) -> Bytes<'_>;
 57	    /// Run `on_push` each time a worker joins or leaves, so its functions do.
 58	    fn on_functions_changed(&self, on_push: OnPush) -> Result<(), String>;
 59	}
  1	//! The Engine seam on a real engine, through `iii-sdk`.
  2	
  3	use bastion_protocol::Link;
  4	use iii_sdk::iii::WorkerMetadata;
  5	use iii_sdk::protocol::{RegisterTriggerInput, TriggerRequest};
  6	use iii_sdk::runtime::IIIConnectionState;
  7	use std::collections::HashMap;
  8	use std::sync::Mutex;
  9	
 10	use iii_sdk::channel::{ChannelReader, StreamChannelRef};
 11	use iii_sdk::trigger::Trigger;
 12	use iii_sdk::{Error, IIIClient, InitOptions, RegisterFunction, register_worker};
 13	use serde_json::{Value, json};
 14	
 15	use super::{Bytes, Call, Engine, OnEvent, OnPush};
 16	
 17	const FUNCTIONS_CHANGED: &str = "bastion::app::functions-changed";
 18	
 19	pub struct IiiEngine {
 20	    url: String,
 21	    client: IIIClient,
 22	    bindings: Mutex<HashMap<String, Trigger>>,
 23	}
 24	
 25	impl IiiEngine {
 26	    pub fn connect(url: &str) -> Self {
 27	        let options = InitOptions {
 28	            metadata: Some(WorkerMetadata {
 29	                name: "bastion-app".into(),
 30	                ..WorkerMetadata::default()
 31	            }),
 32	            namespace: Some("bastion".into()),
 33	            ..InitOptions::default()
 34	        };
 35	        Self {
 36	            url: url.into(),
 37	            client: register_worker(url, options),
 38	            bindings: Mutex::new(HashMap::new()),
 39	        }
 40	    }
 41	}
 42	
 43	impl Engine for IiiEngine {
 44	    fn url(&self) -> &str {
 45	        &self.url
 46	    }
 47	
 48	    fn link(&self) -> Link {
 49	        match self.client.get_connection_state() {
 50	            IIIConnectionState::Connecting => Link::Connecting,
 51	            IIIConnectionState::Connected => Link::Up,
 52	            IIIConnectionState::Reconnecting => Link::Reconnecting,
 53	            IIIConnectionState::Disconnected | IIIConnectionState::Failed => Link::Down,
 54	        }
 55	    }
 56	
 57	    fn call_for<'a>(
 58	        &'a self,
 59	        namespace: &'a str,
 60	        function_id: &'a str,
 61	        payload: Value,
 62	        timeout_ms: u64,
 63	    ) -> Call<'a> {
 64	        Box::pin(async move {
 65	            let mut request = TriggerRequest::new(function_id, payload);
 66	            request.timeout_ms = Some(timeout_ms);
 67	            self.client
 68	                .trigger(request.namespace(namespace))
 69	                .await
 70	                .map_err(|e| e.to_string())
 71	        })
 72	    }
 73	
 74	    // `engine::functions-available` is a trigger type, and `observe` only
 75	    // watches functions, so this binds it the deprecated way (as N3 did).
 76	    #[allow(deprecated)]
 77	    fn on_functions_changed(&self, on_push: OnPush) -> Result<(), String> {
 78	        self.client.register_function(
 79	            FUNCTIONS_CHANGED,
 80	            RegisterFunction::new_async(move |_: Value| {
 81	                on_push();
 82	                async { Ok::<_, Error>(json!({})) }
 83	            }),
 84	        );
 85	        self.client
 86	            .register_trigger(RegisterTriggerInput::new(
 87	                "engine::functions-available",
 88	                FUNCTIONS_CHANGED,
 89	                json!({}),
 90	            ))
 91	            .map(|_| ())
 92	            .map_err(|e| e.to_string())
 93	    }
 94	
 95	    // Trigger types such as `harness::turn-completed` and the `pre-trigger`
 96	    // hook have no `observe` form yet, so this binds them the deprecated way.
 97	    #[allow(deprecated)]
 98	    fn bind(&self, trigger_type: &str, config: Value, on_event: OnEvent) -> Result<String, String> {
 99	        let id = format!("bastion::app::on::{}", uuid::Uuid::new_v4().simple());
100	        self.client.register_function(
101	            &id,
102	            RegisterFunction::new_async(move |event: Value| {
103	                let answer = on_event(event);
104	                async move { Ok::<_, Error>(answer) }
105	            }),
106	        );
107	        let trigger = self
108	            .client
109	            .register_trigger(RegisterTriggerInput::new(trigger_type, &id, config))
110	            .map_err(|e| e.to_string())?;
111	        self.bindings.lock().unwrap().insert(id.clone(), trigger);
112	        Ok(id)
113	    }
114	
115	    fn unbind(&self, id: &str) {
116	        if let Some(trigger) = self.bindings.lock().unwrap().remove(id) {
117	            trigger.unregister();
118	        }
119	    }
120	
121	    fn read_channel(&self, content: Value) -> Bytes<'_> {
122	        Box::pin(async move {
123	            let channel: StreamChannelRef =
124	                serde_json::from_value(content).map_err(|e| format!("not a channel: {e}"))?;
125	            ChannelReader::new(&self.url, &channel)
126	                .read_all()
127	                .await
128	                .map_err(|e| e.to_string())
129	        })
130	    }
131	}

