100	/// The chain's key from the macOS Keychain, made on first use.
101	// ponytail: `security -w` takes the new key as an argument, so it shows in the process list for a moment; use the Keychain API if that matters.
102	pub fn key(machine: &dyn Machine) -> Result<Vec<u8>, String> {
103	    let account = ["-s", SERVICE, "-a", "bastion"];
104	    let found = machine.run(
105	        "security",
106	        &[&["find-generic-password"][..], &account, &["-w"]].concat(),
107	        None,
108	    )?;
109	    if found.success {
110	        return unhex(found.text.trim());
111	    }
112	    let key: Vec<u8> = [uuid::Uuid::new_v4(), uuid::Uuid::new_v4()]
113	        .iter()
114	        .flat_map(|u| *u.as_bytes())
115	        .collect();
116	    let hex: String = key.iter().map(|b| format!("{b:02x}")).collect();
117	    let made = machine.run(
118	        "security",
119	        &[&["add-generic-password"][..], &account, &["-w", &hex]].concat(),
120	        None,
121	    )?;
122	    if !made.success {
123	        return Err(format!(
124	            "the Keychain refused the audit key: {}",
125	            made.text.trim()
126	        ));
127	    }
128	    Ok(key)
129	}
130	
131	fn unhex(text: &str) -> Result<Vec<u8>, String> {
132	    let bad = || "the audit key in the Keychain is not hex".to_string();
133	    if text.len() != 64 {
134	        return Err(bad());
135	    }
136	    (0..text.len())
137	        .step_by(2)
138	        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).map_err(|_| bad()))
139	        .collect()
140	}
