  1	//! The runtime the server's tasks run on. One process-wide `tokio` runtime,
  2	//! made on first use, so a task can start from any thread, including the
  3	//! engine's callbacks.
  4	
  5	use std::future::Future;
  6	use std::sync::OnceLock;
  7	
  8	use tokio::runtime::{Handle, Runtime};
  9	use tokio::task::JoinHandle;
 10	
 11	fn handle() -> &'static Handle {
 12	    static RT: OnceLock<Runtime> = OnceLock::new();
 13	    RT.get_or_init(|| Runtime::new().expect("a tokio runtime"))
 14	        .handle()
 15	}
 16	
 17	pub fn spawn<F>(task: F) -> JoinHandle<F::Output>
 18	where
 19	    F: Future + Send + 'static,
 20	    F::Output: Send + 'static,
 21	{
 22	    handle().spawn(task)
 23	}
 24	
 25	/// Run a future to its end from outside the runtime, as a test does.
 26	pub fn block_on<F: Future>(task: F) -> F::Output {
 27	    handle().block_on(task)
 28	}
  1	//! The Engine seam (PLAN.md §6.2). This module is the only code in the app that
  2	//! imports `iii-sdk` (D19). Everything else holds an `Arc<dyn Engine>`.
  3	
  4	#[cfg(any(test, feature = "fakes"))]
  5	pub mod fake;
  6	mod iii;
  7	
  8	use std::future::Future;
  9	use std::pin::Pin;
 10	use std::sync::Arc;
 11	
 12	use bastion_protocol::Link;
 13	use serde_json::Value;
 14	
 15	pub use iii::IiiEngine;
 16	
 17	/// The namespace the engine registers its own functions in, such as `engine::*`.
 18	pub const DEFAULT_NAMESPACE: &str = "default";
 19	
 20	pub type Call<'a> = Pin<Box<dyn Future<Output = Result<Value, String>> + Send + 'a>>;
 21	
 22	/// Run on each push from the engine. It must return quickly.
 23	pub type OnPush = Arc<dyn Fn() + Send + Sync>;
 24	
 25	/// Handle one trigger event and return the handler's answer (`{}` for a
 26	/// plain event, a decision for a hook). It must return quickly.
 27	pub type OnEvent = Arc<dyn Fn(Value) -> Value + Send + Sync>;
 28	
 29	pub type Bytes<'a> = Pin<Box<dyn Future<Output = Result<Vec<u8>, String>> + Send + 'a>>;
 30	
 31	/// How long a call waits by default. Slow calls, such as booting a VM, pass
 32	/// their own timeout to `call_for`.
 33	pub const CALL_TIMEOUT_MS: u64 = 5_000;
 34	
 35	pub trait Engine: Send + Sync {
 36	    /// The engine's address, as the profile gave it.
 37	    fn url(&self) -> &str;
 38	    /// The link as it is now. The SDK reconnects by itself.
 39	    fn link(&self) -> Link;
 40	    /// Call one function and wait for its answer, up to `CALL_TIMEOUT_MS`.
 41	    fn call<'a>(&'a self, namespace: &'a str, function_id: &'a str, payload: Value) -> Call<'a> {
 42	        self.call_for(namespace, function_id, payload, CALL_TIMEOUT_MS)
 43	    }
 44	    fn call_for<'a>(
 45	        &'a self,
 46	        namespace: &'a str,
 47	        function_id: &'a str,
 48	        payload: Value,
 49	        timeout_ms: u64,
 50	    ) -> Call<'a>;
 51	    /// Run `on_event` for each event of `trigger_type` that matches `config`.
 52	    /// Returns the binding's id for `unbind`.
 53	    fn bind(&self, trigger_type: &str, config: Value, on_event: OnEvent) -> Result<String, String>;
 54	    fn unbind(&self, id: &str);
 55	    /// Read every byte of a content channel, such as `sandbox::fs::read` returns.
 56	    fn read_channel(&self, content: Value) -> Bytes<'_>;
 57	    /// Run `on_push` each time a worker joins or leaves, so its functions do.
 58	    fn on_functions_changed(&self, on_push: OnPush) -> Result<(), String>;
 59	}
  1	//! The Engine seam on a real engine, through `iii-sdk`.
  2	
  3	use bastion_protocol::Link;
  4	use iii_sdk::iii::WorkerMetadata;
  5	use iii_sdk::protocol::{RegisterTriggerInput, TriggerRequest};
  6	use iii_sdk::runtime::IIIConnectionState;
  7	use std::collections::HashMap;
  8	use std::sync::Mutex;
  9	
 10	use iii_sdk::channel::{ChannelReader, StreamChannelRef};
 11	use iii_sdk::trigger::Trigger;
 12	use iii_sdk::{Error, IIIClient, InitOptions, RegisterFunction, register_worker};
 13	use serde_json::{Value, json};
 14	
 15	use super::{Bytes, Call, Engine, OnEvent, OnPush};
 16	
 17	const FUNCTIONS_CHANGED: &str = "bastion::app::functions-changed";
 18	
 19	pub struct IiiEngine {
 20	    url: String,
 21	    client: IIIClient,
 22	    bindings: Mutex<HashMap<String, Trigger>>,
 23	}
 24	
 25	impl IiiEngine {
 26	    pub fn connect(url: &str) -> Self {
 27	        let options = InitOptions {
 28	            metadata: Some(WorkerMetadata {
 29	                name: "bastion-app".into(),
 30	                ..WorkerMetadata::default()
 31	            }),
 32	            namespace: Some("bastion".into()),
 33	            ..InitOptions::default()
 34	        };
 35	        Self {
 36	            url: url.into(),
 37	            client: register_worker(url, options),
 38	            bindings: Mutex::new(HashMap::new()),
 39	        }
 40	    }
 41	}
 42	
 43	impl Engine for IiiEngine {
 44	    fn url(&self) -> &str {
 45	        &self.url
 46	    }
 47	
 48	    fn link(&self) -> Link {
 49	        match self.client.get_connection_state() {
 50	            IIIConnectionState::Connecting => Link::Connecting,
 51	            IIIConnectionState::Connected => Link::Up,
 52	            IIIConnectionState::Reconnecting => Link::Reconnecting,
 53	            IIIConnectionState::Disconnected | IIIConnectionState::Failed => Link::Down,
 54	        }
 55	    }
 56	
 57	    fn call_for<'a>(
 58	        &'a self,
 59	        namespace: &'a str,
 60	        function_id: &'a str,
 61	        payload: Value,
 62	        timeout_ms: u64,
 63	    ) -> Call<'a> {
 64	        Box::pin(async move {
 65	            let mut request = TriggerRequest::new(function_id, payload);
 66	            request.timeout_ms = Some(timeout_ms);
 67	            self.client
 68	                .trigger(request.namespace(namespace))
 69	                .await
 70	                .map_err(|e| e.to_string())
 71	        })
 72	    }
 73	
 74	    // `engine::functions-available` is a trigger type, and `observe` only
 75	    // watches functions, so this binds it the deprecated way (as N3 did).
 76	    #[allow(deprecated)]
 77	    fn on_functions_changed(&self, on_push: OnPush) -> Result<(), String> {
 78	        self.client.register_function(
 79	            FUNCTIONS_CHANGED,
 80	            RegisterFunction::new_async(move |_: Value| {
 81	                on_push();
 82	                async { Ok::<_, Error>(json!({})) }
 83	            }),
 84	        );
 85	        self.client
 86	            .register_trigger(RegisterTriggerInput::new(
 87	                "engine::functions-available",
 88	                FUNCTIONS_CHANGED,
 89	                json!({}),
 90	            ))
 91	            .map(|_| ())
 92	            .map_err(|e| e.to_string())
 93	    }
 94	
 95	    // Trigger types such as `harness::turn-completed` and the `pre-trigger`
 96	    // hook have no `observe` form yet, so this binds them the deprecated way.
 97	    #[allow(deprecated)]
 98	    fn bind(&self, trigger_type: &str, config: Value, on_event: OnEvent) -> Result<String, String> {
 99	        let id = format!("bastion::app::on::{}", uuid::Uuid::new_v4().simple());
100	        self.client.register_function(
101	            &id,
102	            RegisterFunction::new_async(move |event: Value| {
103	                let answer = on_event(event);
104	                async move { Ok::<_, Error>(answer) }
105	            }),
106	        );
107	        let trigger = self
108	            .client
109	            .register_trigger(RegisterTriggerInput::new(trigger_type, &id, config))
110	            .map_err(|e| e.to_string())?;
111	        self.bindings.lock().unwrap().insert(id.clone(), trigger);
112	        Ok(id)
113	    }
114	
115	    fn unbind(&self, id: &str) {
116	        if let Some(trigger) = self.bindings.lock().unwrap().remove(id) {
117	            trigger.unregister();
118	        }
119	    }
120	
121	    fn read_channel(&self, content: Value) -> Bytes<'_> {
122	        Box::pin(async move {
123	            let channel: StreamChannelRef =
124	                serde_json::from_value(content).map_err(|e| format!("not a channel: {e}"))?;
125	            ChannelReader::new(&self.url, &channel)
126	                .read_all()
127	                .await
128	                .map_err(|e| e.to_string())
129	        })
130	    }
131	}

