202	/// Find who is asking, check their role allows what the route does, and
203	/// hand the person to the handler.
204	async fn authorized(State(app): State<App>, mut request: Request, next: Next) -> Response {
205	    let given = request
206	        .headers()
207	        .get(header::AUTHORIZATION)
208	        .and_then(|v| v.to_str().ok())
209	        .and_then(|v| v.strip_prefix("Bearer "))
210	        .unwrap_or_default()
211	        .to_string();
212	    let path = request
213	        .extensions()
214	        .get::<MatchedPath>()
215	        .map(|p| p.as_str().to_string())
216	        .unwrap_or_default();
217	    let act = access::act_for(request.method(), &path);
218	    let person = match access::person(&app.server, &app.owner, &app.token, &given).await {
219	        Ok(person) => person,
220	        Err(why) => return refused(why),
221	    };
222	    let did = format!("{} {}", request.method(), request.uri().path());
223	    let response = match access::check(&person, act) {
224	        Ok(()) => {
225	            request.extensions_mut().insert(person.clone());
226	            next.run(request).await
227	        }
228	        Err(why) => refused(why),
229	    };
230	    if let Some(kind) = audit_kind(act, response.status()) {
231	        note_act(&app, kind, &person, &did);
232	    }
233	    response
234	}
235	
236	/// What the audit log keeps of a request: every change a person makes, and
237	/// every attempt their role refused (D31, D33). Reads are not kept.
238	fn audit_kind(act: Act, status: StatusCode) -> Option<&'static str> {
239	    if status == StatusCode::FORBIDDEN {
240	        Some("refused")
241	    } else if act != Act::Read && status.is_success() {
242	        Some("act")
243	    } else {
244	        None
245	    }
246	}
247	
248	/// Note what `person` did, or tried to do, in the audit log.
249	fn note_act(app: &App, kind: &str, person: &Person, did: &str) {
250	    let Some(factory) = app.server.factory.get() else {
251	        return;
252	    };
253	    if let Ok(log) = factory.gate().audit() {
254	        log.note(bastion_core::audit::Record {
255	            kind: kind.into(),
256	            subject: did.into(),
257	            detail: format!("{} ({:?})", person.name, person.role),
258	        });
259	    }
260	}
261	
262	fn refused(why: Refusal) -> Response {
263	    let (status, error) = match why {
264	        Refusal::Unknown => (StatusCode::UNAUTHORIZED, "no valid token".to_string()),
265	        Refusal::NotReady => (
266	            StatusCode::SERVICE_UNAVAILABLE,
