744 /// What the stream sends: a change with its number, or a request to read
745 /// everything again because changes were missed.
746 enum Out {
747 Change(u64, Change),
748 Resync,
749 }
751 /// The server's changes as server-sent events. A client that names the last
752 /// number it saw gets what it missed first, or a `resync` when the server no
753 /// longer holds it.
754 async fn events(
755 State(app): State<App>,
756 headers: HeaderMap,
757 ) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
758 let bus = &app.server.events;
759 // Subscribe before reading the backlog, so nothing falls between them.
760 let live = bus.subscribe();
761 let last = headers
762 .get("last-event-id")
763 .and_then(|v| v.to_str().ok())
764 .and_then(|v| v.parse::<u64>().ok());
765 let backlog: Vec<Out> = match last.map(|n| bus.since(n)) {
766 None => Vec::new(),
767 Some(Some(missed)) => missed.into_iter().map(|(n, c)| Out::Change(n, c)).collect(),
768 Some(None) => vec![Out::Resync],
769 };
770 let sent = backlog
771 .iter()
772 .filter_map(|o| match o {
773 Out::Change(n, _) => Some(*n),
774 Out::Resync => None,
775 })
776 .max()
777 .or(last);
778 let live = stream::unfold(live, move |mut rx| async move {
779 loop {
780 match rx.recv().await {
781 Ok((n, _)) if sent.is_some_and(|s| n <= s) => continue,
782 Ok((n, change)) => return Some((Out::Change(n, change), rx)),
783 Err(RecvError::Lagged(_)) => return Some((Out::Resync, rx)),
784 Err(RecvError::Closed) => return None,
785 }
786 }
787 });
788 let all = futures_util::StreamExt::map(
789 futures_util::StreamExt::chain(stream::iter(backlog), live),
790 |out| Ok(sse(out)),
791 );
792 Sse::new(all).keep_alive(KeepAlive::default())
793 }
795 fn sse(out: Out) -> Event {
796 match out {
797 Out::Change(n, change) => Event::default()
798 .id(n.to_string())
799 .data(serde_json::to_string(&change).unwrap_or_default()),
800 Out::Resync => Event::default().event("resync").data("{}"),
801 }
802 }
