  1	//! Who is asking, and whether they may (PLAN.md D31). The HTTP layer asks
  2	//! these; the role rules themselves are `bastion_core::people`.
  3	
  4	use axum::http::Method;
  5	use bastion_core::people::{Act, Person, Role};
  6	
  7	use crate::factory::now;
  8	use crate::people_store::hash;
  9	use crate::server::Server;
 10	
 11	/// Why a request was turned away.
 12	#[derive(Debug, PartialEq, Eq)]
 13	pub enum Refusal {
 14	    /// No token, or one this server does not know.
 15	    Unknown,
 16	    /// The people are in the database, which is not open yet.
 17	    NotReady,
 18	    /// Known, but the role does not allow it.
 19	    Forbidden(String),
 20	}
 21	
 22	/// The person a bearer token belongs to. The owner's token, kept in
 23	/// `data/token`, works before the database opens; every other token is
 24	/// looked up by its hash.
 25	pub async fn person(
 26	    server: &Server,
 27	    owner: &Person,
 28	    owner_token: &str,
 29	    given: &str,
 30	) -> Result<Person, Refusal> {
 31	    if given.is_empty() {
 32	        return Err(Refusal::Unknown);
 33	    }
 34	    if given == owner_token {
 35	        return Ok(owner.clone());
 36	    }
 37	    let factory = server.factory.get().ok_or(Refusal::NotReady)?;
 38	    match factory.store().person_for(&hash(given), now()).await {
 39	        Ok(Some(p)) => Ok(p),
 40	        Ok(None) => Err(Refusal::Unknown),
 41	        Err(_) => Err(Refusal::NotReady),
 42	    }
 43	}
 44	
 45	/// What a route does, by its method and matched path. Acting on a job is
 46	/// counted as on one's own here; the handler checks whose job it is.
 47	pub fn act_for(method: &Method, path: &str) -> Act {
 48	    // Token ids are an admin's business, even to read.
 49	    if path == "/tokens" {
 50	        return Act::Manage;
 51	    }
 52	    if method == Method::GET {
 53	        return Act::Read;
 54	    }
 55	    match path {
 56	        "/jobs" | "/issues/{workspace}/{number}/job" => Act::Submit,
 57	        "/jobs/{id}/approve" | "/jobs/{id}/comment" | "/jobs/{id}/stop" | "/held/allow"
 58	        | "/held/refuse" => Act::OnJob { own: true },
 59	        _ => Act::Manage,
 60	    }
 61	}
 62	
 63	/// Whether `person` may do what the route does.
 64	pub fn check(person: &Person, act: Act) -> Result<(), Refusal> {
 65	    if person.role.may(act) {
 66	        return Ok(());
 67	    }
 68	    let what = match act {
 69	        Act::Read => "read",
 70	        Act::Submit => "submit a request",
 71	        Act::OnJob { .. } => "act on a job",
 72	        Act::Manage => "change this server",
 73	    };
 74	    Err(Refusal::Forbidden(format!(
 75	        "{} is a {:?}, which may not {what}",
 76	        person.name, person.role
 77	    )))
 78	}
 79	
 80	/// Whether `person` may act on a job `requester` asked for.
 81	pub fn may_act_on(person: &Person, requester: Option<&str>) -> bool {
 82	    let own = requester == Some(person.name.as_str());
 83	    person.role.may(Act::OnJob { own })
 84	}
 85	
 86	/// A job as `person` should see it: no actions they may not take.
 87	pub fn as_seen_by(
 88	    person: &Person,
 89	    mut job: bastion_protocol::JobSummary,
 90	) -> bastion_protocol::JobSummary {
 91	    if !may_act_on(person, job.requester.as_deref()) {
 92	        job.actions.clear();
 93	    }
 94	    job
 95	}
 96	
 97	/// Whether `person` may act on job `id`: an admin on any, a member only on
 98	/// a job they asked for.
 99	pub async fn on_job(server: &Server, person: &Person, id: &str) -> Result<(), Refusal> {
100	    if person.role == Role::Admin {
101	        return Ok(());
102	    }
103	    let factory = server.factory.get().ok_or(Refusal::NotReady)?;
104	    let record = factory
105	        .store()
106	        .load(id)
107	        .await
108	        .map_err(|_| Refusal::Unknown)?;
109	    let requester = record.runtime.requester.unwrap_or_default();
110	    check(
111	        person,
112	        Act::OnJob {
113	            own: requester == person.name,
114	        },
115	    )
116	    .map_err(|_| Refusal::Forbidden(format!("only {requester} or an admin may act on job {id}")))
117	}
