  1	//! The people on this Bastion server and their tokens (PLAN.md D31). A token
  2	//! is kept only as its SHA-256, so the database never holds one that works.
  3	//! `Store` extends this trait.
  4	
  5	use bastion_core::people::{Person, Role};
  6	use serde::{Deserialize, Serialize};
  7	use serde_json::{Value, json};
  8	use sha2::{Digest, Sha256};
  9	
 10	use crate::store::{Answer, SqlStore, name, parse};
 11	
 12	/// A token as the server shows it: never the token, only what names it.
 13	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
 14	pub struct TokenInfo {
 15	    /// The first 12 characters of its hash, which name it for revoking.
 16	    pub id: String,
 17	    pub person: String,
 18	    pub label: String,
 19	    pub created_at: u64,
 20	    pub last_used: Option<u64>,
 21	}
 22	
 23	/// A token to keep: whose it is, its hash, a label, and when it was made.
 24	pub struct NewToken<'a> {
 25	    pub person: &'a str,
 26	    pub hash: &'a str,
 27	    pub label: &'a str,
 28	    pub at: u64,
 29	}
 30	
 31	pub trait PeopleStore {
 32	    fn people(&self) -> Answer<'_, Vec<Person>>;
 33	    /// Add a person. Adding one who exists changes nothing.
 34	    fn add_person<'a>(&'a self, person: &'a Person) -> Answer<'a, ()>;
 35	    fn set_role<'a>(&'a self, name: &'a str, role: Role) -> Answer<'a, ()>;
 36	    /// Keep a token's hash for `person`.
 37	    fn add_token<'a>(&'a self, token: NewToken<'a>) -> Answer<'a, ()>;
 38	    fn tokens(&self) -> Answer<'_, Vec<TokenInfo>>;
 39	    /// Revoke the token whose hash starts with `id`.
 40	    fn remove_token<'a>(&'a self, id: &'a str) -> Answer<'a, ()>;
 41	    /// Who holds the token with this hash, noting that it was used at `at`.
 42	    fn person_for<'a>(&'a self, hash: &'a str, at: u64) -> Answer<'a, Option<Person>>;
 43	}
 44	
 45	/// A token's SHA-256, as hex.
 46	pub fn hash(token: &str) -> String {
 47	    Sha256::digest(token.trim().as_bytes())
 48	        .iter()
 49	        .map(|b| format!("{b:02x}"))
 50	        .collect()
 51	}
 52	
 53	/// A new token: 128 random bits, as hex.
 54	pub fn new_token() -> String {
 55	    uuid::Uuid::new_v4().simple().to_string()
 56	}
 57	
 58	/// How many characters of a hash name its token.
 59	pub const ID_LEN: usize = 12;
 60	
 61	pub const SCHEMA: [&str; 2] = [
 62	    "CREATE TABLE IF NOT EXISTS people (
 63	        name TEXT PRIMARY KEY CHECK (length(name) > 0),
 64	        role TEXT NOT NULL CHECK (role IN ('admin','member','viewer')),
 65	        created_at INTEGER NOT NULL)",
 66	    "CREATE TABLE IF NOT EXISTS tokens (
 67	        hash TEXT PRIMARY KEY CHECK (length(hash) = 64),
 68	        person TEXT NOT NULL REFERENCES people(name),
 69	        label TEXT NOT NULL,
 70	        created_at INTEGER NOT NULL,
 71	        last_used INTEGER)",
 72	];
 73	
 74	fn person_of(r: &Value) -> Result<Person, String> {
 75	    Ok(Person {
 76	        name: parse(r, "name")?,
 77	        role: parse(r, "role")?,
 78	    })
 79	}
 80	
 81	fn token_of(r: &Value) -> Result<TokenInfo, String> {
 82	    let hash: String = parse(r, "hash")?;
 83	    Ok(TokenInfo {
 84	        id: hash.chars().take(ID_LEN).collect(),
 85	        person: parse(r, "person")?,
 86	        label: parse(r, "label")?,
 87	        created_at: parse(r, "created_at")?,
 88	        last_used: parse(r, "last_used")?,
 89	    })
 90	}
 91	
 92	impl PeopleStore for SqlStore {
 93	    fn people(&self) -> Answer<'_, Vec<Person>> {
 94	        Box::pin(async move {
 95	            let sql = "SELECT name, role FROM people ORDER BY name";
 96	            self.rows(sql, json!([]), person_of).await
 97	        })
 98	    }
 99	
100	    fn add_person<'a>(&'a self, person: &'a Person) -> Answer<'a, ()> {
101	        Box::pin(async move {
102	            let sql =
103	                "INSERT OR IGNORE INTO people (name, role, created_at) VALUES (?, ?, unixepoch())";
104	            self.execute(sql, json!([person.name, name(person.role)]))
105	                .await
106	                .map(|_| ())
107	        })
108	    }
109	
110	    fn set_role<'a>(&'a self, person: &'a str, role: Role) -> Answer<'a, ()> {
111	        Box::pin(async move {
112	            let rows = self
113	                .execute(
114	                    "UPDATE people SET role = ? WHERE name = ? RETURNING name",
115	                    json!([name(role), person]),
116	                )
117	                .await?;
118	            if rows.is_empty() {
119	                return Err(format!("no person named {person}"));
120	            }
121	            Ok(())
122	        })
123	    }
124	
125	    fn add_token<'a>(&'a self, t: NewToken<'a>) -> Answer<'a, ()> {
126	        Box::pin(async move {
127	            let sql = "INSERT INTO tokens (hash, person, label, created_at) VALUES (?, ?, ?, ?)";
128	            self.execute(sql, json!([t.hash, t.person, t.label, t.at]))
129	                .await
130	                .map(|_| ())
131	        })
132	    }
133	
134	    fn tokens(&self) -> Answer<'_, Vec<TokenInfo>> {
135	        Box::pin(async move {
136	            let sql = "SELECT hash, person, label, created_at, last_used FROM tokens ORDER BY person, created_at";
137	            self.rows(sql, json!([]), token_of).await
138	        })
139	    }
