 11	/// Why a request was turned away.
 12	#[derive(Debug, PartialEq, Eq)]
 13	pub enum Refusal {
 14	    /// No token, or one this server does not know.
 15	    Unknown,
 16	    /// The people are in the database, which is not open yet.
 17	    NotReady,
 18	    /// Known, but the role does not allow it.
 19	    Forbidden(String),
