 33	    /// Add a person. Adding one who exists changes nothing.
 34	    fn add_person<'a>(&'a self, person: &'a Person) -> Answer<'a, ()>;
 35	    fn set_role<'a>(&'a self, name: &'a str, role: Role) -> Answer<'a, ()>;
 36	    /// Keep a token's hash for `person`.
 37	    fn add_token<'a>(&'a self, token: NewToken<'a>) -> Answer<'a, ()>;
 38	    fn tokens(&self) -> Answer<'_, Vec<TokenInfo>>;
 39	    /// Revoke the token whose hash starts with `id`.
 40	    fn remove_token<'a>(&'a self, id: &'a str) -> Answer<'a, ()>;
 41	    /// Who holds the token with this hash, noting that it was used at `at`.
 42	    fn person_for<'a>(&'a self, hash: &'a str, at: u64) -> Answer<'a, Option<Person>>;
 43	}
 44	
 45	/// A token's SHA-256, as hex.
 46	pub fn hash(token: &str) -> String {
 47	    Sha256::digest(token.trim().as_bytes())
 48	        .iter()
 49	        .map(|b| format!("{b:02x}"))
 50	        .collect()
 51	}
 52	
 53	/// A new token: 128 random bits, as hex.
 54	pub fn new_token() -> String {
 55	    uuid::Uuid::new_v4().simple().to_string()
 56	}
 57	
 58	/// How many characters of a hash name its token.
 59	pub const ID_LEN: usize = 12;
 60	
 61	pub const SCHEMA: [&str; 2] = [
 62	    "CREATE TABLE IF NOT EXISTS people (
 63	        name TEXT PRIMARY KEY CHECK (length(name) > 0),
 64	        role TEXT NOT NULL CHECK (role IN ('admin','member','viewer')),
 65	        created_at INTEGER NOT NULL)",
 66	    "CREATE TABLE IF NOT EXISTS tokens (
 67	        hash TEXT PRIMARY KEY CHECK (length(hash) = 64),
 68	        person TEXT NOT NULL REFERENCES people(name),
 69	        label TEXT NOT NULL,
 70	        created_at INTEGER NOT NULL,
 71	        last_used INTEGER)",
 72	];
 73	
 74	fn person_of(r: &Value) -> Result<Person, String> {
 75	    Ok(Person {
 76	        name: parse(r, "name")?,
 77	        role: parse(r, "role")?,
 78	    })
 79	}
 80	
 81	fn token_of(r: &Value) -> Result<TokenInfo, String> {
 82	    let hash: String = parse(r, "hash")?;
 83	    Ok(TokenInfo {
 84	        id: hash.chars().take(ID_LEN).collect(),
 85	        person: parse(r, "person")?,
 86	        label: parse(r, "label")?,
 87	        created_at: parse(r, "created_at")?,
 88	        last_used: parse(r, "last_used")?,
 89	    })
 90	}
