  1	//! `bastion-server`, headless (D27): starts or attaches to the stack in
  2	//! `--checkout`, runs the factory on it, and serves the API: on loopback by
  3	//! default, or on `--listen` over TLS (P5).
  4	//!
  5	//! `bastion-server [--checkout DIR] [--data DIR] [--port N] [--engine URL] [--owner NAME]
  6	//!                 [--listen IP --tls-cert PEM --tls-key PEM]`
  7	
  8	use std::path::{Path, PathBuf};
  9	use std::sync::Arc;
 10	
 11	use bastion_server::engine::{Engine, IiiEngine};
 12	use bastion_server::machine::{Machine, ThisMachine};
 13	use bastion_server::server::Server;
 14	use bastion_server::stack::{self, Stack};
 15	use bastion_server::tls::{self, Serving, TlsListener};
 16	use bastion_server::{api, http, rt};
 17	
 18	struct Args {
 19	    /// Who started the server: its admin (D31).
 20	    owner: Option<String>,
 21	    checkout: PathBuf,
 22	    data: PathBuf,
 23	    port: u16,
 24	    engine: String,
 25	    serving: Serving,
 26	}
 27	
 28	/// Flags as `--name value`, each with its default.
 29	// ponytail: flags read by hand; a parser crate when flags grow past these.
 30	fn args() -> Result<Args, String> {
 31	    let given: Vec<String> = std::env::args().skip(1).collect();
 32	    let flag = |name: &str| {
 33	        given
 34	            .iter()
 35	            .position(|a| a == name)
 36	            .and_then(|i| given.get(i + 1).cloned())
 37	    };
 38	    let checkout = flag("--checkout").map_or_else(std::env::current_dir, |d| Ok(d.into()));
 39	    let checkout = checkout.map_err(|e| e.to_string())?;
 40	    Ok(Args {
 41	        owner: flag("--owner"),
 42	        data: flag("--data").map_or_else(|| checkout.join("data/server"), PathBuf::from),
 43	        port: flag("--port").map_or(Ok(49190), |p| p.parse().map_err(|_| format!("--port {p}")))?,
 44	        engine: flag("--engine").unwrap_or_else(|| "ws://127.0.0.1:49160".into()),
 45	        serving: tls::serving(
 46	            flag("--listen").as_deref(),
 47	            flag("--tls-cert").as_deref(),
 48	            flag("--tls-key").as_deref(),
 49	        )?,
 50	        checkout,
 51	    })
 52	}
 53	
 54	/// The token every request must carry, made on first start and kept in
 55	/// `data/token`, readable by this user only.
 56	fn token(data: &Path) -> Result<String, String> {
 57	    let path = data.join("token");
 58	    if let Ok(kept) = std::fs::read_to_string(&path) {
 59	        return Ok(kept.trim().to_string());
 60	    }
 61	    let made = uuid::Uuid::new_v4().simple().to_string();
 62	    std::fs::write(&path, &made).map_err(|e| format!("{}: {e}", path.display()))?;
 63	    #[cfg(unix)]
 64	    {
 65	        use std::os::unix::fs::PermissionsExt;
 66	        let only_me = std::fs::Permissions::from_mode(0o600);
 67	        std::fs::set_permissions(&path, only_me).map_err(|e| e.to_string())?;
 68	    }
 69	    Ok(made)
 70	}
 71	
 72	/// The name in `git config user.name`, or `owner` when it is unset.
 73	fn git_user(machine: &dyn Machine) -> String {
 74	    machine
 75	        .run("git", &["config", "user.name"], None)
 76	        .ok()
 77	        .filter(|out| out.success && !out.text.trim().is_empty())
 78	        .map_or_else(|| "owner".into(), |out| out.text.trim().to_string())
 79	}
 80	
 81	fn main() -> Result<(), String> {
 82	    let a = args()?;
 83	    std::fs::create_dir_all(&a.data).map_err(|e| format!("{}: {e}", a.data.display()))?;
 84	    let token = token(&a.data)?;
 85	    let seed = std::fs::read_to_string(a.checkout.join("seed/governance.sql"))
 86	        .map_err(|e| format!("seed/governance.sql in {}: {e}", a.checkout.display()))?;
 87	    let stack = Stack {
 88	        checkout: a.checkout.clone(),
 89	        port: stack::port(&a.engine).ok_or(format!("no port in {}", a.engine))?,
 90	        log: a.data.join("compose.log"),
 91	    };
 92	    rt::block_on(async move {
 93	        let engine: Arc<dyn Engine> = Arc::new(IiiEngine::connect(&a.engine));
 94	        let machine: Arc<dyn Machine> = Arc::new(ThisMachine);
 95	        let server = Server::new(engine, machine, stack, a.data.clone())?;
 96	        // Start the stack, or attach to the one already running.
 97	        match api::stack::stack_start(&server.stack, &server.machine, &server.engine).await {
 98	            Ok(status) => println!("stack: {:?}", status.state),
 99	            Err(refused) => eprintln!("stack did not start: {refused:?}"),
100	        }
101	        let owner = a
102	            .owner
103	            .clone()
104	            .unwrap_or_else(|| git_user(&*server.machine));
105	        server.start_factory(seed, a.data.join("bundles"), owner.clone());
106	        let app = http::router(server, &token, &owner);
107	        serve(&a, app).await
108	    })
109	}
110	
111	/// Serve `app` where `--listen` says, over TLS when given a certificate.
112	async fn serve(a: &Args, app: axum::Router) -> Result<(), String> {
113	    let at = (a.serving.ip, a.port);
114	    let tcp = tokio::net::TcpListener::bind(at)
115	        .await
116	        .map_err(|e| format!("{}:{}: {e}", at.0, at.1))?;
117	    let scheme = if a.serving.tls.is_some() {
118	        "https"
119	    } else {
120	        "http"
121	    };
122	    println!(
123	        "bastion-server: serving {scheme} on {}:{}, token in {}",
124	        at.0,
125	        at.1,
126	        a.data.join("token").display()
127	    );
128	    let served = match &a.serving.tls {
129	        None => axum::serve(tcp, app).await,
130	        Some((cert, key)) => {
131	            let acceptor = tls::acceptor(cert, key)?;
132	            axum::serve(TlsListener { tcp, acceptor }, app).await
133	        }
134	    };
135	    served.map_err(|e| e.to_string())
136	}
  1	//! One server: the engine it runs on, the machine it runs on, its changes,
  2	//! and the factory once the engine is up (D27).
  3	
  4	use std::path::PathBuf;
  5	use std::sync::Arc;
  6	use std::time::Duration;
  7	
  8	use bastion_core::people::{Person, Role};
  9	use bastion_protocol::{Change, Link};
 10	
 11	use crate::api::factory::FactoryCell;
 12	use crate::engine::Engine;
 13	use crate::events::Bus;
 14	use crate::factory::Factory;
 15	use crate::machine::Machine;
 16	use crate::people_store::PeopleStore;
 17	use crate::stack::Stack;
 18	use crate::store::SqlStore;
 19	
 20	pub struct Server {
 21	    pub engine: Arc<dyn Engine>,
 22	    pub machine: Arc<dyn Machine>,
 23	    pub events: Arc<Bus>,
 24	    pub factory: FactoryCell,
 25	    /// The stack this server runs on, and the checkout that holds it.
 26	    pub stack: Stack,
 27	    /// Where the server writes what it keeps outside the database, such as
 28	    /// an audit export.
 29	    pub data: PathBuf,
 30	}
 31	
 32	impl Server {
 33	    /// A server on `engine`. Its link and its workers' comings and goings
 34	    /// are published as they change.
 35	    pub fn new(
 36	        engine: Arc<dyn Engine>,
 37	        machine: Arc<dyn Machine>,
 38	        stack: Stack,
 39	        data: PathBuf,
 40	    ) -> Result<Arc<Self>, String> {
 41	        let events = Arc::new(Bus::default());
 42	        crate::api::engine::watch(events.clone(), engine.clone());
 43	        let bus = events.clone();
 44	        engine.on_functions_changed(Arc::new(move || bus.publish(Change::Console)))?;
 45	        Ok(Arc::new(Server {
 46	            engine,
 47	            machine,
 48	            events,
 49	            factory: FactoryCell::default(),
 50	            stack,
 51	            data,
 52	        }))
 53	    }
 54	
 55	    /// Once the engine is up: open the store, start the factory, and resume
 56	    /// its jobs. `seed` is the first-run rules and grants (D26); `scratch` is
 57	    /// where the factory keeps its bundles.
 58	    /// `owner` is the person who started the server; they are its admin (D31).
 59	    pub fn start_factory(self: &Arc<Self>, seed: String, scratch: PathBuf, owner: String) {
 60	        let server = self.clone();
 61	        crate::rt::spawn(async move {
 62	            loop {
 63	                if server.engine.link() == Link::Up {
 64	                    match SqlStore::open(server.engine.clone(), &seed).await {
 65	                        Ok(store) => {
 66	                            let admin = Person {
 67	                                name: owner,
 68	                                role: Role::Admin,
 69	                            };
 70	                            if let Err(e) = store.add_person(&admin).await {
 71	                                eprintln!("the owner was not added: {e}");
 72	                            }
 73	                            return server.run(store, scratch);
 74	                        }
 75	                        Err(e) => eprintln!("the store did not open: {e}"),
 76	                    }
 77	                }
 78	                tokio::time::sleep(Duration::from_secs(1)).await;
 79	            }
 80	        });
 81	    }
 82	
 83	    fn run(&self, store: SqlStore, scratch: PathBuf) {
 84	        let bus = self.events.clone();
 85	        let on_change = Arc::new(move |id: &str| bus.publish(Change::Job { id: id.into() }));
 86	        let factory = Factory::new(
 87	            self.engine.clone(),
 88	            Arc::new(store),
 89	            self.machine.clone(),
 90	            on_change,
 91	            scratch,
 92	        );
 93	        if let Err(e) = factory.start() {
 94	            eprintln!("the factory did not start: {e}");
 95	        }
 96	        let _ = self.factory.set(factory);
 97	        // Clients that read before the factory started read again.
 98	        self.events.publish(Change::Job { id: String::new() });
 99	    }
100	}
  1	//! Serving beyond loopback (PLAN.md P5). A Bastion server listens on
  2	//! loopback by default; any other address needs a certificate and key, so
  3	//! tokens never cross a network in the clear.
  4	
  5	use std::net::{IpAddr, SocketAddr};
  6	use std::path::{Path, PathBuf};
  7	use std::sync::Arc;
  8	use std::time::Duration;
  9	
 10	use rustls::pki_types::pem::PemObject;
 11	use rustls::pki_types::{CertificateDer, PrivateKeyDer};
 12	use tokio::net::{TcpListener, TcpStream};
 13	use tokio_rustls::TlsAcceptor;
 14	use tokio_rustls::server::TlsStream;
 15	
 16	/// Where to serve, and the certificate and key when serving TLS.
 17	#[derive(Debug, PartialEq, Eq)]
 18	pub struct Serving {
 19	    pub ip: IpAddr,
 20	    pub tls: Option<(PathBuf, PathBuf)>,
 21	}
 22	
 23	/// What `--listen`, `--tls-cert` and `--tls-key` ask for, refused when it
 24	/// would serve tokens in the clear beyond loopback.
 25	pub fn serving(
 26	    listen: Option<&str>,
 27	    cert: Option<&str>,
 28	    key: Option<&str>,
 29	) -> Result<Serving, String> {
 30	    let ip: IpAddr = listen
 31	        .unwrap_or("127.0.0.1")
 32	        .parse()
 33	        .map_err(|_| format!("--listen {}: not an IP address", listen.unwrap_or_default()))?;
 34	    let tls = match (cert, key) {
 35	        (Some(c), Some(k)) => Some((c.into(), k.into())),
 36	        (None, None) => None,
 37	        _ => return Err("--tls-cert and --tls-key go together".into()),
 38	    };
 39	    if tls.is_none() && !ip.is_loopback() {
 40	        return Err(format!(
 41	            "--listen {ip} is beyond loopback: give --tls-cert and --tls-key"
 42	        ));
 43	    }
 44	    Ok(Serving { ip, tls })
 45	}
 46	
 47	/// A TLS acceptor for the PEM certificate chain and private key.
 48	pub fn acceptor(cert: &Path, key: &Path) -> Result<TlsAcceptor, String> {
 49	    let chain = CertificateDer::pem_file_iter(cert)
 50	        .and_then(|certs| certs.collect::<Result<Vec<_>, _>>())
 51	        .map_err(|e| format!("{}: {e}", cert.display()))?;
 52	    let key = PrivateKeyDer::from_pem_file(key).map_err(|e| format!("{}: {e}", key.display()))?;
 53	    let provider = Arc::new(rustls::crypto::ring::default_provider());
 54	    let config = rustls::ServerConfig::builder_with_provider(provider)
 55	        .with_safe_default_protocol_versions()
 56	        .and_then(|b| b.with_no_client_auth().with_single_cert(chain, key))
 57	        .map_err(|e| e.to_string())?;
 58	    Ok(TlsAcceptor::from(Arc::new(config)))
 59	}
 60	
 61	/// A listener that hands axum only connections that finished a handshake.
 62	pub struct TlsListener {
 63	    pub tcp: TcpListener,
 64	    pub acceptor: TlsAcceptor,
 65	}
 66	
 67	/// How long a client gets to finish its handshake.
 68	const HANDSHAKE: Duration = Duration::from_secs(10);
 69	
 70	impl axum::serve::Listener for TlsListener {
 71	    type Io = TlsStream<TcpStream>;
 72	    type Addr = SocketAddr;
 73	
 74	    // ponytail: handshakes run one at a time, so a slow client delays the
 75	    // next by up to HANDSHAKE; hand them to tasks if a server gets busy.
 76	    async fn accept(&mut self) -> (Self::Io, Self::Addr) {
 77	        loop {
 78	            let (tcp, addr) = axum::serve::Listener::accept(&mut self.tcp).await;
 79	            match tokio::time::timeout(HANDSHAKE, self.acceptor.accept(tcp)).await {
 80	                Ok(Ok(tls)) => return (tls, addr),
 81	                Ok(Err(e)) => eprintln!("tls handshake from {addr}: {e}"),
 82	                Err(_) => eprintln!("tls handshake from {addr}: timed out"),
 83	            }
 84	        }
 85	    }
 86	
 87	    fn local_addr(&self) -> std::io::Result<Self::Addr> {
 88	        self.tcp.local_addr()
 89	    }
 90	}
 91	
 92	#[cfg(test)]
 93	mod tests {
 94	    use super::*;
 95	
 96	    #[test]
 97	    fn loopback_is_the_default_and_needs_no_certificate() {
 98	        let s = serving(None, None, None).unwrap();
 99	        assert_eq!(s.ip, IpAddr::from([127, 0, 0, 1]));
100	        assert_eq!(s.tls, None);
101	        assert!(serving(Some("::1"), None, None).is_ok());
102	    }
103	
104	    #[test]
105	    fn beyond_loopback_needs_a_certificate_and_key() {
106	        let refused = serving(Some("0.0.0.0"), None, None).unwrap_err();
107	        assert!(refused.contains("beyond loopback"), "{refused}");
108	        assert!(serving(Some("0.0.0.0"), Some("c.pem"), None).is_err());
109	        let s = serving(Some("10.0.0.5"), Some("c.pem"), Some("k.pem")).unwrap();
110	        assert_eq!(s.tls, Some(("c.pem".into(), "k.pem".into())));
111	        assert!(serving(Some("example.com"), None, None).is_err());
112	    }
113	
114	    #[test]
115	    fn a_missing_certificate_is_named() {
116	        let Err(e) = acceptor(
117	            Path::new("/nonexistent/c.pem"),
118	            Path::new("/nonexistent/k.pem"),
119	        ) else {
120	            panic!("no certificate, no acceptor");
121	        };
122	        assert!(e.contains("/nonexistent/c.pem"), "{e}");
123	    }
124	}

