  1	//! `bastion-server`, headless (D27): starts or attaches to the stack in
  2	//! `--checkout`, runs the factory on it, and serves the API: on loopback by
  3	//! default, or on `--listen` over TLS (P5).
  4	//!
  5	//! `bastion-server [--checkout DIR] [--data DIR] [--port N] [--engine URL] [--owner NAME]
  6	//!                 [--listen IP --tls-cert PEM --tls-key PEM]`
  7	
  8	use std::path::{Path, PathBuf};
  9	use std::sync::Arc;
 10	
 11	use bastion_server::engine::{Engine, IiiEngine};
 12	use bastion_server::machine::{Machine, ThisMachine};
 13	use bastion_server::server::Server;
 14	use bastion_server::stack::{self, Stack};
 15	use bastion_server::tls::{self, Serving, TlsListener};
 16	use bastion_server::{api, http, rt};
 17	
 18	struct Args {
 19	    /// Who started the server: its admin (D31).
 20	    owner: Option<String>,
 21	    checkout: PathBuf,
 22	    data: PathBuf,
 23	    port: u16,
 24	    engine: String,
 25	    serving: Serving,
 26	}
 27	
 28	/// Flags as `--name value`, each with its default.
 29	// ponytail: flags read by hand; a parser crate when flags grow past these.
 30	fn args() -> Result<Args, String> {
 31	    let given: Vec<String> = std::env::args().skip(1).collect();
 32	    let flag = |name: &str| {
 33	        given
 34	            .iter()
 35	            .position(|a| a == name)
 36	            .and_then(|i| given.get(i + 1).cloned())
 37	    };
 38	    let checkout = flag("--checkout").map_or_else(std::env::current_dir, |d| Ok(d.into()));
 39	    let checkout = checkout.map_err(|e| e.to_string())?;
 40	    Ok(Args {
 41	        owner: flag("--owner"),
 42	        data: flag("--data").map_or_else(|| checkout.join("data/server"), PathBuf::from),
 43	        port: flag("--port").map_or(Ok(49190), |p| p.parse().map_err(|_| format!("--port {p}")))?,
 44	        engine: flag("--engine").unwrap_or_else(|| "ws://127.0.0.1:49160".into()),
 45	        serving: tls::serving(
 46	            flag("--listen").as_deref(),
 47	            flag("--tls-cert").as_deref(),
 48	            flag("--tls-key").as_deref(),
 49	        )?,
 50	        checkout,
 51	    })
 52	}
 53	
 54	/// The token every request must carry, made on first start and kept in
 55	/// `data/token`, readable by this user only.
 56	fn token(data: &Path) -> Result<String, String> {
 57	    let path = data.join("token");
 58	    if let Ok(kept) = std::fs::read_to_string(&path) {
 59	        return Ok(kept.trim().to_string());
 60	    }
 61	    let made = uuid::Uuid::new_v4().simple().to_string();
 62	    std::fs::write(&path, &made).map_err(|e| format!("{}: {e}", path.display()))?;
 63	    #[cfg(unix)]
 64	    {
 65	        use std::os::unix::fs::PermissionsExt;
 66	        let only_me = std::fs::Permissions::from_mode(0o600);
 67	        std::fs::set_permissions(&path, only_me).map_err(|e| e.to_string())?;
 68	    }
 69	    Ok(made)
 70	}
 71	
 72	/// The name in `git config user.name`, or `owner` when it is unset.
 73	fn git_user(machine: &dyn Machine) -> String {
 74	    machine
 75	        .run("git", &["config", "user.name"], None)
 76	        .ok()
 77	        .filter(|out| out.success && !out.text.trim().is_empty())
 78	        .map_or_else(|| "owner".into(), |out| out.text.trim().to_string())
 79	}
 80	
 81	fn main() -> Result<(), String> {
 82	    let a = args()?;
 83	    std::fs::create_dir_all(&a.data).map_err(|e| format!("{}: {e}", a.data.display()))?;
 84	    let token = token(&a.data)?;
 85	    let seed = std::fs::read_to_string(a.checkout.join("seed/governance.sql"))
 86	        .map_err(|e| format!("seed/governance.sql in {}: {e}", a.checkout.display()))?;
 87	    let stack = Stack {
 88	        checkout: a.checkout.clone(),
 89	        port: stack::port(&a.engine).ok_or(format!("no port in {}", a.engine))?,
 90	        log: a.data.join("compose.log"),
 91	    };
 92	    rt::block_on(async move {
 93	        let engine: Arc<dyn Engine> = Arc::new(IiiEngine::connect(&a.engine));
 94	        let machine: Arc<dyn Machine> = Arc::new(ThisMachine);
 95	        let server = Server::new(engine, machine, stack, a.data.clone())?;
 96	        // Start the stack, or attach to the one already running.
 97	        match api::stack::stack_start(&server.stack, &server.machine, &server.engine).await {
 98	            Ok(status) => println!("stack: {:?}", status.state),
 99	            Err(refused) => eprintln!("stack did not start: {refused:?}"),
100	        }
101	        let owner = a
102	            .owner
103	            .clone()
104	            .unwrap_or_else(|| git_user(&*server.machine));
105	        server.start_factory(seed, a.data.join("bundles"), owner.clone());
106	        let app = http::router(server, &token, &owner);
107	        serve(&a, app).await
108	    })
109	}
110	
111	/// Serve `app` where `--listen` says, over TLS when given a certificate.
112	async fn serve(a: &Args, app: axum::Router) -> Result<(), String> {
113	    let at = (a.serving.ip, a.port);
114	    let tcp = tokio::net::TcpListener::bind(at)
115	        .await
116	        .map_err(|e| format!("{}:{}: {e}", at.0, at.1))?;
117	    let scheme = if a.serving.tls.is_some() {
118	        "https"
119	    } else {
120	        "http"
121	    };
122	    println!(
123	        "bastion-server: serving {scheme} on {}:{}, token in {}",
124	        at.0,
125	        at.1,
126	        a.data.join("token").display()
127	    );
128	    let served = match &a.serving.tls {
129	        None => axum::serve(tcp, app).await,
130	        Some((cert, key)) => {
131	            let acceptor = tls::acceptor(cert, key)?;
132	            axum::serve(TlsListener { tcp, acceptor }, app).await
133	        }
134	    };
135	    served.map_err(|e| e.to_string())
136	}
