 28	    /// an audit export.
 29	    pub data: PathBuf,
 30	}
 31	
 32	impl Server {
 33	    /// A server on `engine`. Its link and its workers' comings and goings
 34	    /// are published as they change.
 35	    pub fn new(
 36	        engine: Arc<dyn Engine>,
 37	        machine: Arc<dyn Machine>,
 38	        stack: Stack,
 39	        data: PathBuf,
 40	    ) -> Result<Arc<Self>, String> {
 41	        let events = Arc::new(Bus::default());
 42	        crate::api::engine::watch(events.clone(), engine.clone());
 43	        let bus = events.clone();
 44	        engine.on_functions_changed(Arc::new(move || bus.publish(Change::Console)))?;
 45	        Ok(Arc::new(Server {
 46	            engine,
 47	            machine,
 48	            events,
 49	            factory: FactoryCell::default(),
 50	            stack,
 51	            data,
 52	        }))
 53	    }
 54	
 55	    /// Once the engine is up: open the store, start the factory, and resume
 56	    /// its jobs. `seed` is the first-run rules and grants (D26); `scratch` is
 57	    /// where the factory keeps its bundles.
 58	    /// `owner` is the person who started the server; they are its admin (D31).
 59	    pub fn start_factory(self: &Arc<Self>, seed: String, scratch: PathBuf, owner: String) {
 60	        let server = self.clone();
 61	        crate::rt::spawn(async move {
 62	            loop {
 63	                if server.engine.link() == Link::Up {
 64	                    match SqlStore::open(server.engine.clone(), &seed).await {
 65	                        Ok(store) => {
 66	                            let admin = Person {
 67	                                name: owner,
 68	                                role: Role::Admin,
 69	                            };
 70	                            if let Err(e) = store.add_person(&admin).await {
 71	                                eprintln!("the owner was not added: {e}");
 72	                            }
 73	                            return server.run(store, scratch);
 74	                        }
 75	                        Err(e) => eprintln!("the store did not open: {e}"),
 76	                    }
 77	                }
 78	                tokio::time::sleep(Duration::from_secs(1)).await;
 79	            }
 80	        });
 81	    }
 82	
 83	    fn run(&self, store: SqlStore, scratch: PathBuf) {
 84	        let bus = self.events.clone();
 85	        let on_change = Arc::new(move |id: &str| bus.publish(Change::Job { id: id.into() }));
 86	        let factory = Factory::new(
 87	            self.engine.clone(),
 88	            Arc::new(store),
 89	            self.machine.clone(),
 90	            on_change,
 91	            scratch,
 92	        );
 93	        if let Err(e) = factory.start() {
 94	            eprintln!("the factory did not start: {e}");
 95	        }
 96	        let _ = self.factory.set(factory);
 97	        // Clients that read before the factory started read again.
 98	        self.events.publish(Change::Job { id: String::new() });
 99	    }
100	}
