  1	//! The factory loop (PLAN.md §6.1): load a job, step it with `bastion-core`,
  2	//! save it with its `rev`, run the effects on iii, and tell the page. Every
  3	//! factory rule lives in the core; this file only does what an effect says.
  4	
  5	use std::collections::HashMap;
  6	use std::path::{Path, PathBuf};
  7	use std::sync::{Arc, Mutex};
  8	use std::time::{Duration, SystemTime, UNIX_EPOCH};
  9	
 10	use base64::Engine as _;
 11	use bastion_core::govern::Enforcement;
 12	use bastion_core::review;
 13	use bastion_core::settings::Forge;
 14	use bastion_core::{
 15	    BASE_TAG, Dials, Effect, Event, Job, Outcome, Pipeline, Stage, State, admit, outcome, step,
 16	};
 17	use serde_json::{Value, json};
 18	
 19	use crate::audit_log::{self, AuditLog};
 20	use crate::charter;
 21	use crate::engine::{DEFAULT_NAMESPACE, Engine};
 22	use crate::eval_store::{Eval, EvalRun};
 23	use crate::evals;
 24	use crate::forge;
 25	use crate::gate::Gate;
 26	use crate::machine::Machine;
 27	use crate::settings_store;
 28	use crate::spec;
