 30	use crate::workflow_store;
 31	
 32	const NS: &str = "bastion";
 33	/// At most this many jobs hold a VM (iii-sandbox's `max_concurrent_sandboxes`).
 34	const MAX_VMS: usize = 8;
 35	/// Every turn's model until A7 lets the owner pick one per stage.
 36	// ponytail: one fixed model; A7 moves it into settings.
 37	pub const PROVIDER: &str = "openai";
 38	pub const MODEL: &str = "gpt-5-mini";
 39	const MAX_TURN_STEPS: u64 = 40;
 40	/// The tools a turn may call. A pre-trigger hook pins each to the job's VM.
 41	const TOOLS: [&str; 4] = [
 42	    "sandbox::exec",
 43	    "sandbox::fs::read",
 44	    "sandbox::fs::write",
 45	    "sandbox::fs::ls",
 46	];
 47	const REPO: &str = "/work/repo";
 48	
 49	/// Where a request came from, and the pipeline it runs.
 50	#[derive(Default)]
 51	pub struct Submission {
 52	    /// The tracker issue it came from, as its URL.
 53	    pub issue: Option<String>,
 54	    pub pipeline: Pipeline,
 55	    /// The person asking (D31).
 56	    pub requester: Option<String>,
 57	    /// The workflow to run, by id (D35); none runs `pipeline`.
 58	    pub workflow: Option<String>,
 59	}
 60	/// The VM tag a read-only turn's tree is put back to.
 61	const BEFORE_TURN: &str = "bastion-before-turn";
 62	const SLOW_MS: u64 = 180_000;
 63	/// How a turn reaches its VM. The pre-trigger hook replaces `sandbox_id`, so
 64	/// the turn passes any value; without one some calls fail their schema.
 65	const TOOL_GUIDE: &str = "\
 66	Your tools run in this job's VM. The repository is at /work/repo.
 67	Call sandbox::exec with {\"sandbox_id\": \"job\", \"argv\": [\"git\", \"-C\", \"/work/repo\", \"status\"]},
 68	and sandbox::fs::read, sandbox::fs::write and sandbox::fs::ls with {\"sandbox_id\": \"job\", \"path\": ...}.
 69	Bastion points \"job\" at your VM. Only committed work leaves the VM.
 70	Run each program directly as an argv, never through bash -lc, and pass
 71	\"timeout_ms\": 60000 so a hung command fails instead of stalling the turn.
 72	Run Python tests with [\"python3\", \"-m\", \"pytest\", \"-q\", \"/work/repo\"].
 73	Your reply ends your turn. Keep calling tools until the work is done and
 74	committed, and reply only then. Do not describe a next step; take it.";
 75	const SAVE_TRIES: usize = 3;
 76	/// How many times CI is polled, 20 s apart, before the land gives up.
 77	const CI_POLLS: u32 = 90;
 78	
 79	pub type OnChange = Arc<dyn Fn(&str) + Send + Sync>;
 80	type BoxFuture<T> = std::pin::Pin<Box<dyn std::future::Future<Output = T> + Send>>;
 81	
 82	pub struct Factory {
 83	    engine: Arc<dyn Engine>,
 84	    store: Arc<dyn Store>,
 85	    machine: Arc<dyn Machine>,
 86	    on_change: OnChange,
 87	    /// Where bundles pass through on their way between worktree and VM.
 88	    scratch: PathBuf,
 89	    /// The trigger bindings each running turn or land holds, by job.
 90	    bindings: Mutex<HashMap<String, Vec<String>>>,
 91	    gate: Arc<Gate>,
 92	}
 93	
 94	/// The text of a session's last assistant message.
 95	pub async fn final_reply(engine: &dyn Engine, session: &str) -> Result<String, String> {
 96	    let out = engine
 97	        .call(NS, "session::messages", json!({ "session_id": session }))
 98	        .await?;
 99	    out["messages"]
100	        .as_array()
101	        .into_iter()
102	        .flatten()
103	        .rev()
104	        .find(|m| m["message"]["role"] == "assistant")
105	        .map(|m| {
106	            m["message"]["content"]
107	                .as_array()
108	                .into_iter()
109	                .flatten()
110	                .filter_map(|part| part["text"].as_str())
111	                .collect::<Vec<_>>()
112	                .join("\n")
113	        })
114	        .ok_or_else(|| format!("session {session} has no reply"))
115	}
116	
117	pub fn now() -> u64 {
118	    SystemTime::now()
119	        .duration_since(UNIX_EPOCH)
120	        .map_or(0, |d| d.as_secs())
121	}
122	
123	pub fn short_id() -> String {
124	    uuid::Uuid::new_v4().simple().to_string()[..8].to_string()
125	}
126	
127	impl Factory {
128	    pub fn new(
129	        engine: Arc<dyn Engine>,
130	        store: Arc<dyn Store>,
131	        machine: Arc<dyn Machine>,
132	        on_change: OnChange,
133	        scratch: PathBuf,
134	    ) -> Arc<Self> {
135	        let audit = audit_log::key(&*machine)
136	            .map(|key| AuditLog::start(store.clone(), key, audit_log::WRITE_LIMIT));
137	        if let Err(e) = &audit {
138	            eprintln!("the audit has no key, so the gate refuses every call: {e}");
139	        }
140	        let gate = Gate::new(store.clone(), engine.clone(), on_change.clone(), audit);
141	        Arc::new(Self {
142	            engine,
143	            store,
144	            machine,
145	            on_change,
146	            scratch,
147	            bindings: Mutex::new(HashMap::new()),
148	            gate,
149	        })
150	    }
151	
152	    pub fn store(&self) -> &Arc<dyn Store> {
153	        &self.store
154	    }
155	
156	    pub fn engine(&self) -> &Arc<dyn Engine> {
157	        &self.engine
158	    }
159	
160	    pub fn gate(&self) -> &Arc<Gate> {
161	        &self.gate
162	    }
163	
164	    /// Put every `sandbox::*` call a turn makes through the gate, which pins
165	    /// it to the job's VM, then resume.
166	    pub fn start(self: &Arc<Self>) -> Result<(), String> {
167	        let gate = self.gate.clone();
168	        self.engine.bind(
169	            "harness::hook::pre-trigger",
170	            json!({ "functions": ["sandbox::*"], "on_error": "fail_closed", "timeout_ms": 5000 }),
171	            Arc::new(move |envelope: Value| gate.judge(&envelope)),
172	        )?;
173	        let factory = self.clone();
174	        crate::rt::spawn(async move {
175	            if let Err(e) = factory.gate.reload().await {
176	                eprintln!("the gate has no policy, so it refuses every call: {e}");
177	            }
178	            factory.resume().await
179	        });
180	        Ok(())
181	    }
182	
183	    #[cfg(test)]
184	    pub async fn submit(
185	        self: &Arc<Self>,
186	        workspace: &str,
187	        request: &str,
188	    ) -> Result<String, String> {
189	        self.submit_with(workspace, request, Submission::default())
190	            .await
191	    }
192	
193	    /// Submit a request, with the tracker issue it came from if any.
194	    pub async fn submit_with(
195	        self: &Arc<Self>,
196	        workspace: &str,
197	        request: &str,
198	        how: Submission,
199	    ) -> Result<String, String> {
200	        let id = format!("j{}", short_id());
201	        let at = now();
202	        let mut job = Job::new(id.clone(), workspace.into(), request.into(), at).on(how.pipeline);
203	        let mut workflow_version = None;
204	        if let Some(w) = &how.workflow {
205	            let dials = settings_store::current(&*self.store).await?.dials;
206	            (job, workflow_version) =
207	                workflow_store::start_on(&*self.store, &dials, w, job).await?;
208	        }
209	        let record = Record {
210	            job,
211	            runtime: Runtime {
212	                issue: how.issue,
213	                requester: how.requester,
214	                workflow: how.workflow,
215	                workflow_version,
216	                ..Runtime::default()
217	            },
218	            rev: 1,
219	            created_at: at,
220	        };
221	        self.store.insert(&record).await?;
222	        (self.on_change)(&id);
223	        self.pump();
224	        Ok(id)
225	    }
226	
227	    /// Submit one request of an eval under one arm: a trial job, kept with
228	    /// its eval run before it is admitted.
229	    pub async fn submit_trial(
230	        self: &Arc<Self>,
231	        e: &Eval,
232	        mut run: EvalRun,
233	    ) -> Result<String, String> {
234	        let id = format!("j{}", short_id());
235	        let at = now();
236	        let record = Record {
237	            job: Job::new(id.clone(), e.workspace.clone(), run.request.clone(), at),
238	            runtime: Runtime::default(),
239	            rev: 1,
240	            created_at: at,
241	        };
242	        self.store.insert(&record).await?;
243	        run.job = id.clone();
244	        self.store.add_eval_run(&run).await?;
245	        (self.on_change)(&id);
246	        self.pump();
247	        Ok(id)
248	    }
249	
250	    /// The dials a job runs under: a trial's own, or the owner's. A job on
251	    /// a kept workflow takes each step's dial from the step.
252	    async fn dials_for(&self, id: &str) -> Result<Dials, String> {
253	        Ok(match self.store.eval_run_of(id).await? {
254	            Some(_) => Dials {
255	                trial: true,
256	                ..Dials::default()
257	            },
258	            None => settings_store::current(&*self.store).await?.dials,
259	        })
260	    }
261	
262	    /// Step one job with one event, save it, and run its effects.
263	    pub async fn apply(self: &Arc<Self>, id: &str, event: Event) -> Result<(), String> {
264	        self.clone().apply_owned(id.to_string(), event).await
265	    }
266	
267	    // Boxed, because an effect it spawns can call it again.
268	    fn apply_owned(self: Arc<Self>, id: String, event: Event) -> BoxFuture<Result<(), String>> {
269	        Box::pin(async move {
270	            for _ in 0..SAVE_TRIES {
271	                let mut record = self.store.load(&id).await?;
272	                let dials = self.dials_for(&id).await?;
273	                let (job, effects) = step(&record.job, &event, now(), &dials);
274	                if job == record.job && effects.is_empty() {
275	                    return Ok(());
276	                }
277	                record.job = job;
278	                match self.store.save(&record).await {
279	                    Ok(rev) => {
280	                        record.rev = rev;
281	                        // Artifacts are written before the page hears of the
282	                        // change, so a page that reads at once sees them. Dark
283	                        // decisions go in the audit log in the order they fell,
284	                        // and a split's parts are kept before the page hears.
285	                        let (artifacts, rest): (Vec<Effect>, Vec<Effect>) =
286	                            effects.into_iter().partition(|e| {
287	                                matches!(
288	                                    e,
289	                                    Effect::RecordArtifact { .. }
290	                                        | Effect::CaptureDiff
291	                                        | Effect::DarkDecided { .. }
292	                                        | Effect::Split { .. }
293	                                )
294	                            });
295	                        for effect in artifacts {
296	                            self.clone().run(record.clone(), effect).await;
297	                        }
298	                        (self.on_change)(&id);
299	                        for effect in rest {
300	                            let (factory, record) = (self.clone(), record.clone());
301	                            crate::rt::spawn(factory.run(record, effect));
302	                        }
303	                        self.pump();
304	                        return Ok(());
305	                    }
306	                    Err(e) if e == STALE => continue,
307	                    Err(e) => return Err(e),
308	                }
309	            }
310	            Err(STALE.into())
311	        })
312	    }
313	
314	    /// Admit queued jobs while VMs are free.
315	    // ponytail: two pumps at once can each see a free slot; a per-app lock fixes it if the cap is ever overrun.
316	    fn pump(self: &Arc<Self>) {
317	        let factory = self.clone();
318	        crate::rt::spawn(async move {
319	            let Ok(records) = factory.store.jobs().await else {
320	                return;
321	            };
322	            let jobs: Vec<Job> = records.into_iter().map(|r| r.job).collect();
323	            for id in admit(&jobs, MAX_VMS) {
324	                let _ = factory.apply(&id, Event::Admitted).await;
325	            }
326	        });
327	    }
328	
329	    /// Change where a job runs, without stepping it.
330	    async fn set_runtime(&self, id: &str, change: impl Fn(&mut Runtime)) -> Result<Record, String> {
331	        for _ in 0..SAVE_TRIES {
332	            let mut record = self.store.load(id).await?;
333	            change(&mut record.runtime);
334	            match self.store.save(&record).await {
335	                Ok(rev) => {
336	                    record.rev = rev;
337	                    return Ok(record);
338	                }
339	                Err(e) if e == STALE => continue,
340	                Err(e) => return Err(e),
341	            }
342	        }
343	        Err(STALE.into())
344	    }
345	
346	    fn run(self: Arc<Self>, record: Record, effect: Effect) -> BoxFuture<()> {
347	        Box::pin(self.run_effect(record, effect))
348	    }
349	
350	    async fn run_effect(self: Arc<Self>, record: Record, effect: Effect) {
351	        let id = record.job.id.clone();
352	        let failed = match effect {
353	            Effect::DarkDecided { stage } => {
354	                self.dark_decided(&id, stage);
355	                None
356	            }
357	            Effect::Provision => match self.provision(&record).await {
358	                Ok(()) => self.apply(&id, Event::Provisioned).await.err(),
359	                Err(error) => self
360	                    .apply(&id, Event::ProvisionFailed { error })
361	                    .await
362	                    .err(),
363	            },
364	            Effect::StartTurn {
365	                stage,
366	                brief,
367	                cap_secs,
368	                ..
369	            } => {
370	                let started = self.start_turn(&record, stage, &brief, cap_secs).await;
371	                let failed = |error| Event::TurnFinished {
372	                    outcome: Outcome::Failed { error },
373	                };
374	                self.report_failure(&id, started, failed).await
375	            }
376	            Effect::RunStep { stage } => self.run_step(&record, stage).await,
377	            Effect::Split { parts } => self.add_parts(&record, parts).await.err(),
378	            Effect::RecordArtifact { stage, body } => {
379	                let artifact = Artifact {
380	                    stage,
381	                    body,
382	                    created_at: now(),
383	                };
384	                self.store.add_artifact(&id, &artifact).await.err()
385	            }
386	            Effect::CaptureDiff => {
387	                if let Some(sandbox) = &record.runtime.sandbox {
388	                    self.gate.stop_hooks(&id, sandbox).await;
389	                }
390	                let body = self
391	                    .diff(&record)
392	                    .await
393	                    .unwrap_or_else(|e| format!("The diff could not be read: {e}"));
394	                self.review(&id, &body);
395	                let artifact = Artifact {
396	                    stage: Stage::Review,
397	                    body,
398	                    created_at: now(),
399	                };
400	                self.store.add_artifact(&id, &artifact).await.err()
401	            }
402	            Effect::Land => {
403	                let landed = self.land(&record).await;
404	                let failed = |error| Event::LandFailed { error };
405	                self.report_failure(&id, landed, failed).await
406	            }
407	            Effect::WatchCi | Effect::Merge => self.forge_effect(&record, effect).await,
408	            Effect::Teardown => {
409	                self.grade_trial(&record);
410	                self.teardown(&record).await.err()
411	            }
412	        };
413	        if let Some(error) = failed {
414	            eprintln!("job {id}: {error}");
415	        }
416	    }
