700 /// After a turn: a read-only stage's tree goes back, and a turn that
701 /// writes code has its commits kept in the worktree, so a lost VM loses
702 /// none. A bring-back error means no new commits, which is not a failure.
703 async fn tidy_after_turn(&self, record: &Record) {
704 let stage = record.job.stage;
705 match &record.runtime.sandbox {
706 Some(sandbox) if stage.read_only() => self.put_back(sandbox).await,
707 Some(_) if writes_code(stage) => {
708 let _ = self.bring_back(record).await;
709 }
710 _ => {}
711 }
