714 /// A read-only stage leaves no change behind, not even a commit: the tree
715 /// goes back to the tag made before the turn, or to `HEAD` without one.
716 async fn put_back(&self, sandbox: &str) {
717 let to_tag = ["git", "-C", REPO, "reset", "-q", "--hard", BEFORE_TURN];
718 if self.vm_exec(sandbox, &to_tag).await.is_err() {
719 let _ = self.vm_exec(sandbox, &to_tag[..6]).await;
720 }
721 let _ = self
722 .vm_exec(sandbox, &["git", "-C", REPO, "clean", "-q", "-fd"])
723 .await;
724 }
