754 /// The build's commits against the branch it started from, from the VM.
755 async fn diff(&self, record: &Record) -> Result<String, String> {
756 let sandbox = record.runtime.sandbox.clone().ok_or("no VM")?;
757 let worktree = record.runtime.worktree.clone().ok_or("no worktree")?;
758 let (_, branch) = self.worktree_path(&worktree).await?;
759 let out = self
760 .vm_exec(
761 &sandbox,
762 &["git", "-C", REPO, "diff", &format!("origin/{branch}..HEAD")],
763 )
764 .await?;
765 let text = out["stdout"].as_str().unwrap_or_default();
766 let mut body = if text.trim().is_empty() {
767 "No commits: the build left nothing to land.".to_string()
768 } else {
769 text.to_string()
770 };
771 // Work the turn left uncommitted does not land, so the review says so.
772 let status = self
773 .vm_exec(&sandbox, &["git", "-C", REPO, "status", "--porcelain"])
774 .await?;
775 let dirty: Vec<&str> = status["stdout"]
776 .as_str()
777 .unwrap_or_default()
778 .lines()
779 .filter(|l| !l.contains("__pycache__"))
780 .collect();
781 if !dirty.is_empty() {
782 body.push_str("\n\nNot committed, so it will not land:\n");
783 body.push_str(&dirty.join("\n"));
784 }
785 Ok(body)
786 }
