561 async fn start_turn(
562 self: &Arc<Self>,
563 record: &Record,
564 stage: Stage,
565 brief: &str,
566 cap_secs: u64,
567 ) -> Result<(), String> {
568 let job = &record.job;
569 let sandbox = record.runtime.sandbox.clone().ok_or("no VM")?;
570 let session = format!("{}-{}", job.id, short_id());
571 self.set_runtime(&job.id, |r| r.session = Some(session.clone()))
572 .await?;
573 self.listen_for_turn(&job.id, &session)?;
574 // The owner may have edited the rows directly (D26).
575 self.gate.reload().await?;
576
577 let mut message = String::new();
578 if let Some(worktree) = &record.runtime.worktree {
579 let (path, _) = self.worktree_path(worktree).await?;
580 self.gate
581 .set_charter(&job.id, charter::read(&*self.machine, &path));
582 self.load_arm(&job.id).await?;
583 for name in charter::BRIEF_FILES {
584 if let Ok(text) = self.machine.read(&path.join(name)) {
585 message.push_str(&format!(
586 "The repository's charter ({name}):\n<charter>\n{text}\n</charter>\n\n"
587 ));
588 }
589 }
590 }
591 if stage.read_only() || stage == Stage::Falsify {
592 // Where the tree goes back to after the turn, commits included:
593 // by `put_back` for a read-only turn, by the baseline after falsify.
594 self.vm_exec(&sandbox, &["git", "-C", REPO, "tag", "-f", BEFORE_TURN])
595 .await?;
596 }
597 message.push_str(TOOL_GUIDE);
598 message.push_str("\n\n");
599 message.push_str(&self.gate.rules(&job.id));
600 message.push_str(brief);
601 let settings = settings_store::current(&*self.store).await?;
602 let model = settings.model(stage);
603 self.engine
604 .call(
605 NS,
606 "approval::set-mode",
607 json!({ "session_id": session, "mode": "full" }),
608 )
609 .await?;
610 self.engine
611 .call_for(NS, "harness::send", json!({
612 "session_id": session, "provider": model.provider, "model": model.model, "message": message,
613 "options": { "max_turns": MAX_TURN_STEPS, "functions": { "allow": TOOLS }, "metadata": { "sandbox_id": sandbox, "job": job.id, "stage": stage } },
614 }), 60_000)
615 .await?;
616 let factory = self.clone();
617 let (id, turn) = (job.id.clone(), session.clone());
618 crate::rt::spawn(async move {
619 tokio::time::sleep(Duration::from_secs(cap_secs)).await;
620 factory.turn_done(&id, &turn, true).await;
621 });
622 Ok(())
623 }
