641 /// A turn ended, or ran past its cap. Ignored when the job moved on.
642 async fn turn_done(self: &Arc<Self>, id: &str, session: &str, timed_out: bool) {
643 let Ok(record) = self.store.load(id).await else {
644 return;
645 };
646 if record.runtime.session.as_deref() != Some(session) || record.job.state != State::Running
647 {
648 return;
649 }
650 let result = if timed_out {
651 Outcome::Failed {
652 error: format!(
653 "the turn ran past {} minutes",
654 bastion_core::TURN_CAP_SECS / 60
655 ),
656 }
657 } else {
658 match self
659 .engine
660 .call(NS, "harness::status", json!({ "session_id": session }))
661 .await
662 {
663 Ok(status) if status["status"] != "completed" => return,
664 Ok(status) => match status["result_error"].as_str() {
665 Some(error) => Outcome::Failed {
666 error: error.into(),
667 },
668 None => match self.final_reply(session).await {
669 Ok(reply) => usable(record.job.stage, outcome(&reply)),
670 Err(error) => Outcome::Failed { error },
671 },
672 },
673 Err(error) => Outcome::Failed { error },
674 }
675 };
676 self.release(id);
677 evals::meter(&*self.engine, &*self.store, &record.job, session).await;
678 self.tidy_after_turn(&record).await;
679 let _ = self
680 .apply(id, Event::TurnFinished { outcome: result })
681 .await;
682 }
