726 /// Run a step the factory runs itself, and report how it went.
727 // ponytail: a workspace has no setup steps until A9, so prepare passes at
728 // once; any other step fails until it has a runner.
729 async fn run_step(self: &Arc<Self>, record: &Record, stage: Stage) -> Option<String> {
730 let event = match stage {
731 Stage::Prepare => Event::StepPassed,
732 Stage::Baseline | Stage::Verify | Stage::Acceptance => {
733 self.acceptance_step(record, stage).await
734 }
735 Stage::Checks => self.checks_step(record).await,
736 Stage::Command => self.command_step(record).await,
737 Stage::Ship => self
738 .ship(record)
739 .await
740 .unwrap_or_else(|detail| Event::StepStuck { detail }),
741 // ponytail: nothing watches CD yet, so a deploy passes; watching the merge commit's checks comes with a workspace that deploys.
742 Stage::Deploy => Event::StepPassed,
743 _ => Event::StepFailed {
744 detail: format!("Bastion does not run the {stage:?} step yet."),
745 },
746 };
747 let event = match event {
748 Event::StepStuck { detail } if vm_lost(&detail) => Event::VmLost,
749 other => other,
750 };
751 self.apply(&record.job.id, event).await.err()
752 }
