767 "No commits: the build left nothing to land.".to_string()
768 } else {
769 text.to_string()
770 };
771 // Work the turn left uncommitted does not land, so the review says so.
772 let status = self
773 .vm_exec(&sandbox, &["git", "-C", REPO, "status", "--porcelain"])
774 .await?;
