776 .as_str()
777 .unwrap_or_default()
778 .lines()
779 .filter(|l| !l.contains("__pycache__"))
780 .collect();
781 if !dirty.is_empty() {
782 body.push_str("\n\nNot committed, so it will not land:\n");
783 body.push_str(&dirty.join("\n"));
784 }
785 Ok(body)
786 }
