956 /// Judge a build's diff by the constraints that bind it. An enforced
957 /// rule it breaks sends the work back once with the rule and what broke
958 /// it; if the next build breaks it the same way, the owner decides.
959 fn review(self: &Arc<Self>, id: &str, diff: &str) {
960 let findings = review::review(diff, &self.gate.constraints(id));
961 let repeated = self.gate.reviewed(id, &findings);
962 let Some(f) = findings.iter().find(|f| f.rung == Enforcement::Enforced) else {
963 return;
964 };
965 if repeated {
966 eprintln!(
967 "job {id}: the build did not fix {}; it waits for the owner",
968 f.constraint
969 );
970 return;
971 }
972 let text = format!(
973 "Bastion sent this back: {} {}. Put them back as they were, with the same names.",
974 f.rule, f.detail
975 );
976 let (factory, id) = (self.clone(), id.to_string());
977 crate::rt::spawn(async move {
978 if let Err(e) = factory.apply(&id, Event::Commented { text }).await {
979 eprintln!("job {id}: the review could not send the work back: {e}");
980 }
981 });
982 }
