  1	//! The gate in the factory (PLAN.md A5, D20, D21). Every `sandbox::*` call a
  2	//! turn makes reaches `judge` through a `pre-trigger` hook, and
  3	//! `bastion_core::govern::gate` decides it. The hook reads the policy from
  4	//! memory and hands every record to the audit writer, so a slow store never
  5	//! stalls a turn. Without an audit writer it refuses every call.
  6	
  7	use std::collections::HashMap;
  8	use std::sync::{Arc, Mutex, RwLock};
  9	
 10	use bastion_core::Stage;
 11	use bastion_core::audit;
 12	use bastion_core::eval::Override;
 13	use bastion_core::govern::{self, Call, Capability, Constraint, Decision, Verdict};
 14	use serde_json::{Value, json};
 15	
 16	use crate::audit_log::AuditLog;
 17	use crate::charter::{self, Charter};
 18	use crate::engine::{DEFAULT_NAMESPACE, Engine};
 19	use crate::factory::{OnChange, now};
 20	use crate::store::{HeldCall, Store};
 21	
 22	const NS: &str = "bastion";
 23	const RUN_MS: u64 = 120_000;
 24	
 25	/// The rules the gate judges by, as the store last gave them.
 26	struct Policy {
 27	    constraints: Vec<Constraint>,
 28	    grants: Vec<Capability>,
 29	}
 30	
 31	pub struct Gate {
 32	    store: Arc<dyn Store>,
 33	    engine: Arc<dyn Engine>,
 34	    on_change: OnChange,
 35	    /// None until the first load. Until then every call is refused.
 36	    policy: RwLock<Option<Policy>>,
 37	    /// The writer, or why there is none (such as no Keychain key).
 38	    audit: Result<Arc<AuditLog>, String>,
 39	    /// Each job's charter, read from its worktree when a turn starts.
 40	    charters: Mutex<HashMap<String, Arc<Charter>>>,
 41	    /// Each job's repository hook runs, latest last.
 42	    hook_runs: Mutex<HashMap<String, Vec<String>>>,
 43	    /// What each job's latest review diff broke, by constraint.
 44	    findings: Mutex<HashMap<String, Vec<String>>>,
 45	    /// The rungs an eval's arm sets for each of its trial jobs.
 46	    overrides: Mutex<HashMap<String, Vec<Override>>>,
 47	    /// Each job's approved acceptance test files, which no turn may write.
 48	    // ponytail: kept in memory; a server restart after the baseline forgets them, and verify still catches a change.
 49	    approved: Mutex<HashMap<String, Vec<String>>>,
 50	}
 51	
 52	/// The factory's rule for one approved acceptance test (A8): enforced, so
 53	/// a turn that writes it is refused.
 54	fn approved_test(file: &str) -> Constraint {
 55	    Constraint {
 56	        id: format!("approved-test:{file}"),
 57	        rule: format!("Do not change {file}: it is an approved acceptance test."),
 58	        function: "sandbox::fs::write".into(),
 59	        contains: format!("/work/repo/{file}"),
 60	        rung: bastion_core::govern::Enforcement::Enforced,
 61	        source: bastion_core::govern::Source::Owner,
 62	    }
 63	}
 64	
 65	/// What the rules read from a call: its command line in any of the shapes
 66	/// `sandbox::exec` takes (`argv`, or `cmd` with `args`), else its path.
 67	fn call_of(call: &Value) -> Call {
 68	    let arguments = &call["arguments"];
 69	    let words = |v: &Value| -> Vec<String> {
 70	        v.as_array()
 71	            .into_iter()
 72	            .flatten()
 73	            .filter_map(|w| w.as_str().map(String::from))
 74	            .collect()
 75	    };
 76	    let mut line = words(&arguments["argv"]);
 77	    if let Some(cmd) = arguments["cmd"].as_str() {
 78	        line.push(cmd.into());
 79	        line.extend(words(&arguments["args"]));
 80	    }
 81	    let text = if line.is_empty() {
 82	        arguments["path"].as_str().unwrap_or_default().to_string()
 83	    } else {
 84	        line.join(" ")
 85	    };
 86	    Call {
 87	        function: call["function_id"].as_str().unwrap_or_default().into(),
 88	        text,
 89	    }
 90	}
 91	
 92	/// A call's arguments as a Claude Code hook reads `tool_input`.
 93	fn tool_input(held: &HeldCall) -> Value {
 94	    match held.call.function.as_str() {
 95	        "sandbox::exec" => json!({ "command": held.call.text }),
 96	        _ => json!({ "file_path": held.call.text, "content": held.arguments["content"] }),
 97	    }
 98	}
 99	
100	fn text_result(text: &str, details: Value, is_error: bool) -> Value {
101	    json!({ "content": [{ "type": "text", "text": text }], "details": details, "is_error": is_error })
102	}
103	
104	impl Gate {
105	    pub fn new(
106	        store: Arc<dyn Store>,
107	        engine: Arc<dyn Engine>,
108	        on_change: OnChange,
109	        audit: Result<Arc<AuditLog>, String>,
110	    ) -> Arc<Self> {
111	        Arc::new(Self {
112	            store,
113	            engine,
114	            on_change,
115	            policy: RwLock::new(None),
116	            audit,
117	            charters: Mutex::new(HashMap::new()),
118	            hook_runs: Mutex::new(HashMap::new()),
119	            findings: Mutex::new(HashMap::new()),
120	            overrides: Mutex::new(HashMap::new()),
121	            approved: Mutex::new(HashMap::new()),
122	        })
123	    }
124	
125	    /// Use this charter for the job's calls from now on, and record it.
126	    pub fn set_charter(&self, job: &str, charter: Charter) {
127	        let files = if charter.files.is_empty() {
128	            "none: owner defaults".into()
129	        } else {
130	            charter.files.join(", ")
131	        };
132	        let detail = format!(
133	            "{files}; {} rules, {} hooks before calls, {} stop hooks",
134	            charter.constraints.len(),
135	            charter.before.len(),
136	            charter.stop.len()
137	        );
138	        self.note("charter", job, detail);
139	        self.charters
140	            .lock()
141	            .unwrap()
142	            .insert(job.into(), Arc::new(charter));
143	    }
144	
145	    pub fn charter(&self, job: &str) -> Option<Arc<Charter>> {
146	        self.charters.lock().unwrap().get(job).cloned()
147	    }
148	
149	    pub fn hook_runs(&self, job: &str) -> Vec<String> {
150	        self.hook_runs
151	            .lock()
152	            .unwrap()
153	            .get(job)
154	            .cloned()
155	            .unwrap_or_default()
156	    }
157	
158	    fn ran(&self, job: &str, kind: &str, ran: &charter::Ran) {
159	        self.note(kind, job, ran.line());
160	        self.hook_runs
161	            .lock()
162	            .unwrap()
163	            .entry(job.into())
164	            .or_default()
165	            .push(ran.line());
166	    }
167	
168	    /// Read the constraints and grants again, after a change to either.
169	    pub async fn reload(&self) -> Result<(), String> {
170	        let policy = Policy {
171	            constraints: self.store.constraints().await?,
172	            grants: self.store.capabilities().await?,
173	        };
174	        *self.policy.write().unwrap() = Some(policy);
175	        Ok(())
176	    }
177	
178	    pub fn audit(&self) -> Result<&Arc<AuditLog>, String> {
179	        self.audit.as_ref().map_err(Clone::clone)
180	    }
181	
182	    fn note(&self, kind: &str, subject: &str, detail: String) {
183	        if let Ok(log) = &self.audit {
184	            log.note(audit::Record {
185	                kind: kind.into(),
186	                subject: subject.into(),
187	                detail,
188	            });
189	        }
190	    }
191	
192	    /// Keep and record what a job's review diff broke. True when the findings
193	    /// repeat the last review's, so the build did not fix them.
194	    pub fn reviewed(&self, job: &str, findings: &[bastion_core::review::Finding]) -> bool {
195	        let lines: Vec<String> = findings
196	            .iter()
197	            .map(|f| format!("{} ({:?}): {}", f.constraint, f.rung, f.detail))
198	            .collect();
199	        for line in &lines {
200	            self.note("review", job, line.clone());
201	        }
202	        let last = self
203	            .findings
204	            .lock()
205	            .unwrap()
206	            .insert(job.into(), lines.clone());
207	        !lines.is_empty() && last.as_ref() == Some(&lines)
208	    }
209	
210	    pub fn findings(&self, job: &str) -> Vec<String> {
211	        self.findings
212	            .lock()
213	            .unwrap()
214	            .get(job)
215	            .cloned()
216	            .unwrap_or_default()
217	    }
218	
219	    /// Refuse every write to these files in the job's turns from now on.
220	    pub fn protect(&self, job: &str, files: Vec<String>) {
221	        self.note("protect", job, files.join(", "));
222	        self.approved.lock().unwrap().insert(job.into(), files);
223	    }
224	
225	    /// Judge a trial job under its arm's rungs from now on.
226	    pub fn set_overrides(&self, job: &str, overrides: Vec<Override>) {
227	        let detail = overrides
228	            .iter()
229	            .map(|o| format!("{o:?}"))
230	            .collect::<Vec<_>>()
231	            .join("; ");
232	        self.note("arm", job, detail);
233	        self.overrides.lock().unwrap().insert(job.into(), overrides);
234	    }
235	
236	    /// Record an eval's creation.
237	    pub fn note_eval(&self, e: &crate::eval_store::Eval, requests: usize) {
238	        let base = &e.base[..7.min(e.base.len())];
239	        let detail = format!(
240	            "{}: {requests} requests from {} at {base}",
241	            e.name, e.workspace
242	        );
243	        self.note("eval", &e.id, detail);
244	    }
245	
246	    /// The owner's grants, with the job's arm's rungs set.
247	    fn grants(&self, job: &str) -> Vec<Capability> {
248	        let mut grants: Vec<Capability> = self
249	            .policy
250	            .read()
251	            .unwrap()
252	            .iter()
253	            .flat_map(|p| p.grants.clone())
254	            .collect();
255	        if let Some(o) = self.overrides.lock().unwrap().get(job) {
256	            bastion_core::eval::apply(&mut [], &mut grants, o);
257	        }
258	        grants
259	    }
260	
261	    /// The owner's constraints and the job's charter's, together, with the
262	    /// job's arm's rungs set.
263	    pub fn constraints(&self, job: &str) -> Vec<Constraint> {
264	        let mut all: Vec<Constraint> = self
265	            .policy
266	            .read()
267	            .unwrap()
268	            .iter()
269	            .flat_map(|p| p.constraints.clone())
270	            .collect();
271	        all.extend(
272	            self.charter(job)
273	                .into_iter()
274	                .flat_map(|c| c.constraints.clone()),
275	        );
276	        if let Some(files) = self.approved.lock().unwrap().get(job) {
277	            all.extend(files.iter().map(|f| approved_test(f)));
278	        }
279	        if let Some(o) = self.overrides.lock().unwrap().get(job) {
280	            bastion_core::eval::apply(&mut all, &mut [], o);
281	        }
282	        all
283	    }
284	
285	    /// Every rule, for the brief. The agent is told each rule at every rung.
286	    pub fn rules(&self, job: &str) -> String {
287	        let rules: Vec<String> = self
288	            .constraints(job)
289	            .iter()
290	            .map(|c| format!("- {}", c.rule))
291	            .collect();
292	        if rules.is_empty() {
293	            return String::new();
294	        }
295	        format!("Rules for this job:\n{}\n\n", rules.join("\n"))
296	    }
297	
298	    /// The hook: decide one call, pin it to the job's VM, and record it.
299	    pub fn judge(self: &Arc<Self>, envelope: &Value) -> Value {
300	        let call = call_of(&envelope["call"]);
301	        let job = envelope["metadata"]["job"]
302	            .as_str()
303	            .unwrap_or_default()
304	            .to_string();
305	        let stage: Option<Stage> =
306	            serde_json::from_value(envelope["metadata"]["stage"].clone()).ok();
307	        let verdict = match (&*self.policy.read().unwrap(), stage, &self.audit) {
308	            (_, _, Err(why)) => Verdict {
309	                decision: Decision::Deny {
310	                    reason: format!("The gate cannot record this call, so it refuses it: {why}"),
311	                },
312	                flagged: vec![],
313	            },
314	            (Some(_), Some(stage), Ok(_)) => {
315	                govern::gate(&call, stage, &self.constraints(&job), &self.grants(&job))
316	            }
317	            _ => Verdict {
318	                decision: Decision::Deny {
319	                    reason: "The gate cannot judge this call: it has no policy or no stage.".into(),
320	                },
321	                flagged: vec![],
322	            },
323	        };
324	        self.note("gate", &job, bastion_core::eval::describe(&call, &verdict));
325	        let hooks: Vec<String> = self
326	            .charter(&job)
327	            .iter()
328	            .flat_map(|c| c.before.iter())
329	            .filter(|h| h.functions.contains(&call.function.as_str()))
330	            .map(|h| h.command.clone())
331	            .collect();
332	        let held = || HeldCall {
333	            id: envelope["call"]["id"].as_str().unwrap_or_default().into(),
334	            job: job.clone(),
335	            session: envelope["session_id"].as_str().unwrap_or_default().into(),
336	            turn: envelope["turn_id"].as_str().unwrap_or_default().into(),
337	            call: call.clone(),
338	            arguments: envelope["call"]["arguments"].clone(),
339	            at: now(),
340	        };
341	        match verdict.decision {
342	            // The repository's hooks run first, in the VM, so the call waits on them.
343	            Decision::Continue if !hooks.is_empty() => {
344	                let (gate, held) = (self.clone(), held());
345	                crate::rt::spawn(async move { gate.before(held, hooks).await });
346	                json!({ "decision": "hold", "reason": "The repository's hooks run first." })
347	            }
348	            Decision::Continue => {
349	                let mut arguments = envelope["call"]["arguments"].clone();
350	                arguments["sandbox_id"] = envelope["metadata"]["sandbox_id"].clone();
351	                json!({ "decision": "continue", "mutations": { "arguments": arguments } })
352	            }
353	            Decision::Deny { reason } => json!({ "decision": "deny", "reason": reason }),
354	            Decision::Hold { reason } => {
355	                self.keep(held());
356	                json!({ "decision": "hold", "reason": reason })
357	            }
358	        }
359	    }
360	
361	    /// Save a held call for the job page, off the hook's path.
362	    fn keep(&self, held: HeldCall) {
363	        let (store, on_change) = (self.store.clone(), self.on_change.clone());
364	        crate::rt::spawn(async move {
365	            match store.hold(&held).await {
366	                Ok(()) => on_change(&held.job),
367	                Err(e) => eprintln!("job {}: the held call was not saved: {e}", held.job),
368	            }
369	        });
370	    }
371	
372	    async fn find(&self, job: &str, id: &str) -> Result<HeldCall, String> {
373	        let held = self.store.held(job).await?;
374	        held.into_iter()
375	            .find(|h| h.id == id)
376	            .ok_or_else(|| format!("no held call {id} on job {job}"))
377	    }
378	
379	    /// Send a held call its result, so the parked turn goes on, and record
380	    /// what the owner did as `kind`.
381	    async fn resolve(&self, held: &HeldCall, result: Value, kind: &str) -> Result<(), String> {
382	        let mut detail = format!("{} {}", held.call.function, held.call.text);
383	        if result["is_error"] == true {
384	            detail.push_str(&format!(
385	                ": {}",
386	                result["content"][0]["text"].as_str().unwrap_or_default()
387	            ));
388	        }
389	        let mut payload = json!({
390	            "session_id": held.session, "turn_id": held.turn, "function_call_id": held.id, "action": "deliver",
391	        });
392	        payload
393	            .as_object_mut()
394	            .unwrap()
395	            .extend(result.as_object().cloned().unwrap_or_default());
396	        self.engine
397	            .call(NS, "harness::function::resolve", payload)
398	            .await?;
399	        self.store.release(&held.id).await?;
400	        self.note(kind, &held.job, detail);
401	        (self.on_change)(&held.job);
402	        Ok(())
403	    }
404	
405	    /// Run the repository's hooks on a call. Exit 2 from any of them refuses
406	    /// it with the hook's output; otherwise the call runs.
407	    async fn before(&self, held: HeldCall, hooks: Vec<String>) {
408	        let outcome = match self.sandbox(&held.job).await {
409	            Ok(sandbox) => {
410	                let input = json!({
411	                    "hook_event_name": "PreToolUse", "cwd": "/work/repo",
412	                    "tool_name": bastion_core::charter::tool_name(&held.call.function),
413	                    "tool_input": tool_input(&held),
414	                });
415	                let mut refused = None;
416	                for command in hooks {
417	                    let ran = charter::run(&*self.engine, &sandbox, &command, &input).await;
418	                    self.ran(&held.job, "hook", &ran);
419	                    if ran.refuses() {
420	                        refused = Some(ran);
421	                        break;
422	                    }
423	                }
424	                match refused {
425	                    Some(ran) => {
426	                        let text = format!(
427	                            "The repository's hook refused this call: {}",
428	                            ran.output.trim()
429	                        );
430	                        self.resolve(&held, text_result(&text, Value::Null, true), "hook-refuse")
431	                            .await
432	                    }
433	                    None => self.run_held(&held, "hook-pass").await,
434	                }
435	            }
436	            Err(e) => Err(e),
437	        };
438	        if let Err(e) = outcome {
439	            eprintln!("job {}: a hooked call was not settled: {e}", held.job);
440	        }
441	    }
442	
443	    /// Run each `Stop` hook of the job's charter in its VM, and keep the results.
444	    pub async fn stop_hooks(&self, job: &str, sandbox: &str) {
445	        let Some(charter) = self.charter(job) else {
446	            return;
447	        };
448	        let input = json!({ "hook_event_name": "Stop", "cwd": "/work/repo" });
449	        for command in &charter.stop {
450	            let ran = charter::run(&*self.engine, sandbox, command, &input).await;
451	            self.ran(job, "stop-hook", &ran);
452	        }
453	    }
454	
455	    async fn sandbox(&self, job: &str) -> Result<String, String> {
456	        Ok(self
457	            .store
458	            .load(job)
459	            .await?
460	            .runtime
461	            .sandbox
462	            .ok_or("the job has no VM")?)
463	    }
464	
465	    /// Run exactly this call once, in the job's VM, and deliver its result.
466	    /// The hold dropped the VM pin, so the app pins it again here (N8).
467	    pub async fn allow_once(&self, job: &str, id: &str) -> Result<(), String> {
468	        let held = self.find(job, id).await?;
469	        self.run_held(&held, "allow-once").await
470	    }
471	
472	    async fn run_held(&self, held: &HeldCall, kind: &str) -> Result<(), String> {
473	        let sandbox = self
474	            .store
475	            .load(&held.job)
476	            .await?
477	            .runtime
478	            .sandbox
479	            .ok_or("the job has no VM")?;
480	        let mut arguments = held.arguments.clone();
481	        arguments["sandbox_id"] = json!(sandbox);
482	        let ran = self
483	            .engine
484	            .call_for(DEFAULT_NAMESPACE, &held.call.function, arguments, RUN_MS)
485	            .await;
486	        let result = match ran {
487	            Ok(out) => text_result(&out.to_string(), out, false),
488	            Err(e) => text_result(&e, Value::Null, true),
489	        };
490	        self.resolve(held, result, kind).await
491	    }
492	
493	    /// Refuse a held call, and tell the agent why and what to do instead.
494	    pub async fn refuse(&self, job: &str, id: &str, feedback: &str) -> Result<(), String> {
495	        let held = self.find(job, id).await?;
496	        let text = format!("The owner refused this call: {feedback}");
497	        self.resolve(&held, text_result(&text, Value::Null, true), "refuse")
498	            .await
499	    }
500	
501	    /// Refuse every call still held for a job that stopped or finished.
502	    pub async fn clear(&self, job: &str) {
503	        for held in self.store.held(job).await.unwrap_or_default() {
504	            let result = text_result("The job stopped.", Value::Null, true);
505	            if let Err(e) = self.resolve(&held, result, "clear").await {
506	                eprintln!("job {job}: a held call was not cleared: {e}");
507	            }
508	        }
509	    }
510	
511	    /// Add an owner's constraint. Its id must be new.
512	    pub async fn add_constraint(&self, c: Constraint) -> Result<(), String> {
513	        if c.id.trim().is_empty() || c.rule.trim().is_empty() {
514	            return Err("a constraint needs an id and a rule".into());
515	        }
516	        if self.store.constraints().await?.iter().any(|x| x.id == c.id) {
517	            return Err(format!("a constraint {} already exists", c.id));
518	        }
519	        self.store.set_constraint(&c).await?;
520	        self.reload().await?;

