405	    /// Run the repository's hooks on a call. Exit 2 from any of them refuses
406	    /// it with the hook's output; otherwise the call runs.
407	    async fn before(&self, held: HeldCall, hooks: Vec<String>) {
408	        let outcome = match self.sandbox(&held.job).await {
409	            Ok(sandbox) => {
410	                let input = json!({
411	                    "hook_event_name": "PreToolUse", "cwd": "/work/repo",
412	                    "tool_name": bastion_core::charter::tool_name(&held.call.function),
413	                    "tool_input": tool_input(&held),
414	                });
415	                let mut refused = None;
416	                for command in hooks {
417	                    let ran = charter::run(&*self.engine, &sandbox, &command, &input).await;
418	                    self.ran(&held.job, "hook", &ran);
419	                    if ran.refuses() {
420	                        refused = Some(ran);
421	                        break;
422	                    }
423	                }
424	                match refused {
425	                    Some(ran) => {
426	                        let text = format!(
427	                            "The repository's hook refused this call: {}",
428	                            ran.output.trim()
429	                        );
430	                        self.resolve(&held, text_result(&text, Value::Null, true), "hook-refuse")
431	                            .await
432	                    }
433	                    None => self.run_held(&held, "hook-pass").await,
434	                }
435	            }
436	            Err(e) => Err(e),
437	        };
438	        if let Err(e) = outcome {
439	            eprintln!("job {}: a hooked call was not settled: {e}", held.job);
440	        }
441	    }
