529 /// Set the live policy to an eval arm's rungs, and record the eval the
530 /// owner acted on with each move.
531 pub async fn apply_arm(
532 &self,
533 eval: &str,
534 arm: &str,
535 overrides: &[Override],
536 ) -> Result<(), String> {
537 let (mut constraints, mut grants) = (
538 self.store.constraints().await?,
539 self.store.capabilities().await?,
540 );
541 let (was_c, was_g) = (constraints.clone(), grants.clone());
542 bastion_core::eval::apply(&mut constraints, &mut grants, overrides);
543 for (c, was) in constraints
544 .iter()
545 .zip(&was_c)
546 .filter(|(c, w)| c.rung != w.rung)
547 {
548 self.store.set_constraint(c).await?;
549 self.note(
550 "apply-eval",
551 &c.id,
552 format!("{eval} arm {arm}: {:?} -> {:?}", was.rung, c.rung),
553 );
554 }
555 for (g, was) in grants.iter().zip(&was_g).filter(|(g, w)| g.rung != w.rung) {
556 self.store.set_capability(g).await?;
557 let subject = format!("{:?} {}", g.stage, g.function);
558 self.note(
559 "apply-eval",
560 &subject,
561 format!("{eval} arm {arm}: {:?} -> {:?}", was.rung, g.rung),
562 );
563 }
564 self.note("eval", eval, format!("the owner applied arm {arm}"));
565 self.reload().await
566 }
