568 /// Move a constraint one rung up or down its ladder, and record it.
569 pub async fn move_constraint(&self, id: &str, up: bool) -> Result<(), String> {
570 let constraints = self.store.constraints().await?;
571 let mut c = constraints
572 .into_iter()
573 .find(|c| c.id == id)
574 .ok_or(format!("no constraint {id}"))?;
575 let was = c.rung;
576 c.rung = if up { was.promote() } else { was.demote() };
577 self.store.set_constraint(&c).await?;
578 self.reload().await?;
579 self.note(
580 if up { "promote" } else { "demote" },
581 id,
582 format!("{was:?} -> {:?}", c.rung),
583 );
584 Ok(())
585 }
