587 /// Move a grant one rung up or down its ladder, and record it.
588 pub async fn move_capability(
589 &self,
590 stage: Stage,
591 function: &str,
592 up: bool,
593 ) -> Result<(), String> {
594 let grants = self.store.capabilities().await?;
595 let mut g = grants
