  1	//! The server's changes, numbered and pushed to every client (D10, D29).
  2	//! A client that reconnects names the last number it saw and gets what it
  3	//! missed, as long as the server still holds it.
  4	
  5	use std::collections::VecDeque;
  6	use std::sync::Mutex;
  7	use std::time::{SystemTime, UNIX_EPOCH};
  8	
  9	use bastion_protocol::Change;
 10	use tokio::sync::broadcast;
 11	
 12	/// How many recent changes a reconnect can replay.
 13	const KEPT: usize = 256;
 14	
 15	pub struct Bus {
 16	    tx: broadcast::Sender<(u64, Change)>,
 17	    /// The latest changes, oldest first, and the next number to give.
 18	    kept: Mutex<(VecDeque<(u64, Change)>, u64)>,
 19	}
 20	
 21	impl Default for Bus {
 22	    fn default() -> Self {
 23	        // Numbers start from the boot time, so a number from before a
 24	        // restart is always older than any this server gives.
 25	        let boot = SystemTime::now()
 26	            .duration_since(UNIX_EPOCH)
 27	            .map_or(0, |d| d.as_millis() as u64);
 28	        Bus {
 29	            tx: broadcast::channel(KEPT).0,
 30	            kept: Mutex::new((VecDeque::new(), boot * 1000)),
 31	        }
 32	    }
 33	}
 34	
 35	impl Bus {
 36	    pub fn publish(&self, change: Change) {
 37	        let mut kept = self.kept.lock().unwrap();
 38	        let n = kept.1;
 39	        kept.1 += 1;
 40	        kept.0.push_back((n, change.clone()));
 41	        if kept.0.len() > KEPT {
 42	            kept.0.pop_front();
 43	        }
 44	        // No subscriber is not an error.
 45	        let _ = self.tx.send((n, change));
 46	    }
 47	
 48	    pub fn subscribe(&self) -> broadcast::Receiver<(u64, Change)> {
 49	        self.tx.subscribe()
 50	    }
 51	
 52	    /// The changes after `last`. `None` when `last` is not one this server
 53	    /// still holds, so the client must read everything again.
 54	    pub fn since(&self, last: u64) -> Option<Vec<(u64, Change)>> {
 55	        let kept = self.kept.lock().unwrap();
 56	        let held = kept.0.front().map_or(kept.1, |(n, _)| *n);
 57	        (held <= last + 1 && last < kept.1)
 58	            .then(|| kept.0.iter().filter(|(n, _)| *n > last).cloned().collect())
 59	    }
 60	}
