  1	//! Bastion's worker for OpenAI-compatible hosts (PLAN.md K3): Together,
  2	//! Fireworks, Qwen through DashScope, a local Ollama. Each host the admin
  3	//! lists is one llm-router provider; its key, if it needs one, is set like
  4	//! any provider's (D34).
  5	
  6	mod host;
  7	mod wire;
  8	
  9	use std::collections::{BTreeMap, BTreeSet, HashSet};
 10	use std::sync::{Arc, Mutex};
 11	
 12	use host::{Ctx, Live, WORKER};
 13	use iii_sdk::iii::WorkerMetadata;
 14	use iii_sdk::{Error, InitOptions, RegisterFunction, register_worker};
 15	use serde_json::{Value, json};
 16	use tokio::signal::unix::{SignalKind, signal};
 17	
 18	const HOSTS: &str = "hosts";
 19	/// Ids of removed hosts. The router still lists them, so the server lets
 20	/// them be added again.
 21	const RETIRED: &str = "retired";
 22	
 23	fn valid_id(id: &str) -> bool {
 24	    let allowed = |c: char| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_';
 25	    (1..=64).contains(&id.len()) && id.chars().all(allowed)
 26	}
 27	
 28	fn checked_host(h: &Value, seen: &mut HashSet<String>) -> Result<Value, String> {
 29	    let id = h["id"].as_str().unwrap_or_default().trim();
 30	    let name = h["name"].as_str().unwrap_or_default().trim();
 31	    let url = h["api_url"].as_str().unwrap_or_default().trim();
 32	    if !valid_id(id) {
 33	        return Err(format!(
 34	            "a host id is 1 to 64 of a-z, 0-9, - and _, not {id:?}"
 35	        ));
 36	    }
 37	    if !(url.starts_with("http://") || url.starts_with("https://")) {
 38	        return Err(format!("{id}: the URL must start with http:// or https://"));
 39	    }
 40	    if !seen.insert(id.to_string()) {
 41	        return Err(format!("{id} is listed twice"));
 42	    }
 43	    let name = if name.is_empty() { id } else { name };
 44	    Ok(json!({ "id": id, "name": name, "api_url": url }))
 45	}
 46	
 47	/// The hosts as given, trimmed, or why they cannot be kept.
 48	fn checked(hosts: &Value) -> Result<Vec<Value>, String> {
 49	    let mut seen = HashSet::new();
 50	    let given = hosts.as_array().ok_or("hosts must be a list")?;
 51	    given.iter().map(|h| checked_host(h, &mut seen)).collect()
 52	}
 53	
 54	type Registry = Mutex<BTreeMap<String, Live>>;
 55	
 56	/// Make the registered hosts match `hosts`: drop every host, retire the
 57	/// ones no longer listed, register each.
 58	fn apply(ctx: &Arc<Ctx>, live: &Registry, hosts: &[Value]) {
 59	    let mut live = live.lock().unwrap();
 60	    for (id, was) in std::mem::take(&mut *live) {
 61	        was.unregister();
 62	        if !hosts.iter().any(|h| h["id"] == id.as_str()) {
 63	            tokio::spawn(host::retire(ctx.clone(), was.host));
 64	        }
 65	    }
 66	    for h in hosts {
 67	        let id = h["id"].as_str().unwrap_or_default().to_string();
 68	        live.insert(id, host::register(ctx, h));
 69	    }
 70	}
 71	
 72	fn ids(list: &Value, field: Option<&str>) -> BTreeSet<String> {
 73	    let items = list.as_array().into_iter().flatten();
 74	    let id = |v: &Value| field.map_or(v, |f| &v[f]).as_str().map(String::from);
 75	    items.filter_map(id).collect()
 76	}
 77	
 78	/// Every id that was a host and is not one now.
 79	fn retired(was_retired: &Value, was: &Value, hosts: &[Value]) -> Vec<String> {
 80	    let now = ids(&json!(hosts), Some("id"));
 81	    let mut all = ids(was_retired, None);
 82	    all.extend(ids(was, Some("id")));
 83	    all.retain(|id| !now.contains(id));
 84	    all.into_iter().collect()
 85	}
 86	
 87	async fn set(ctx: Arc<Ctx>, live: Arc<Registry>, input: Value) -> Result<Value, Error> {
 88	    let hosts = checked(&input[HOSTS]).map_err(Error::Handler)?;
 89	    let gone = retired(&ctx.kept(RETIRED).await, &ctx.kept(HOSTS).await, &hosts);
 90	    ctx.keep(RETIRED, json!(gone))
 91	        .await
 92	        .map_err(Error::Handler)?;
 93	    ctx.keep(HOSTS, json!(hosts))
 94	        .await
 95	        .map_err(Error::Handler)?;
 96	    apply(&ctx, &live, &hosts);
 97	    Ok(json!({ HOSTS: hosts }))
 98	}
 99	
100	fn connect() -> iii_sdk::IIIClient {
101	    let url = std::env::var("III_URL").unwrap_or_else(|_| "ws://127.0.0.1:49160".into());
102	    let metadata = WorkerMetadata {
103	        name: WORKER.into(),
104	        ..WorkerMetadata::default()
105	    };
106	    let options = InitOptions {
107	        metadata: Some(metadata),
108	        namespace: Some("bastion".into()),
109	        ..InitOptions::default()
110	    };
111	    register_worker(&url, options)
112	}
113	
114	#[tokio::main]
115	async fn main() {
116	    let ctx = Ctx::new(connect());
117	    let live: Arc<Registry> = Arc::default();
118	    let (c, l) = (ctx.clone(), live.clone());
119	    ctx.iii.register_function(
120	        "bastion::openai_compat::hosts::set",
121	        RegisterFunction::new_async(move |input: Value| set(c.clone(), l.clone(), input)),
122	    );
123	    let c = ctx.clone();
124	    ctx.iii.register_function(
125	        "bastion::openai_compat::hosts::list",
126	        RegisterFunction::new_async(move |_: Value| {
127	            let c = c.clone();
128	            async move {
129	                let (hosts, retired) = (c.kept(HOSTS).await, c.kept(RETIRED).await);
130	                Ok::<_, Error>(json!({ HOSTS: hosts, RETIRED: retired }))
131	            }
132	        }),
133	    );
134	    let kept = checked(&ctx.kept(HOSTS).await).unwrap_or_default();
135	    apply(&ctx, &live, &kept);
136	    signal(SignalKind::terminate())
137	        .expect("a SIGTERM handler")
138	        .recv()
139	        .await;
140	    ctx.iii.shutdown();
141	}
142	
143	#[cfg(test)]
144	mod tests {
145	    use super::*;
146	
147	    #[test]
148	    fn hosts_are_trimmed_named_and_refused_when_they_cannot_be_providers() {
149	        let given =
150	            json!([{ "id": " ollama ", "api_url": "http://localhost:11434/v1/chat/completions" }]);
151	        let hosts = checked(&given).unwrap();
152	        assert_eq!(hosts[0]["id"], "ollama");
153	        assert_eq!(hosts[0]["name"], "ollama");
154	        let bad_id = json!([{ "id": "Ollama::x", "api_url": "http://h" }]);
155	        assert!(checked(&bad_id).is_err());
156	        let bad_url = json!([{ "id": "h", "api_url": "ftp://h" }]);
157	        assert!(checked(&bad_url).is_err());
158	        let twice =
159	            json!([{ "id": "h", "api_url": "http://a" }, { "id": "h", "api_url": "http://b" }]);
160	        assert!(checked(&twice).is_err());
161	        assert!(checked(&Value::Null).is_err());
162	    }
163	
164	    #[test]
165	    fn a_removed_host_is_retired_until_it_is_added_again() {
166	        let was = json!([{ "id": "a" }, { "id": "b" }]);
167	        assert_eq!(
168	            retired(&json!(["c"]), &was, &[json!({ "id": "a" })]),
169	            ["b", "c"]
170	        );
171	        assert_eq!(
172	            retired(&json!(["b"]), &json!(null), &[json!({ "id": "b" })]),
173	            Vec::<String>::new()
174	        );
175	    }
176	}
  1	//! One llm-router provider per host: its four functions, its declaration
  2	//! to the router, its catalog, and its turns.
  3	
  4	use std::collections::HashMap;
  5	use std::sync::{Arc, Mutex};
  6	use std::time::Duration;
  7	
  8	use iii_sdk::channel::{ChannelWriter, StreamChannelRef};
  9	use iii_sdk::protocol::{RegisterTriggerInput, TriggerRequest};
 10	use iii_sdk::runtime::FunctionRef;
 11	use iii_sdk::trigger::Trigger;
 12	use iii_sdk::{Error, IIIClient, RegisterFunction};
 13	use serde_json::{Value, json};
 14	use tokio::task::AbortHandle;
 15	
 16	use crate::wire;
 17	
 18	pub const WORKER: &str = "bastion-openai-compat";
 19	const NAMESPACE: &str = "bastion";
 20	/// The router's idle timeout is 120 s; a ping keeps a slow host's turn alive.
 21	const PING: Duration = Duration::from_secs(25);
 22	
 23	/// What every host's functions share.
 24	pub struct Ctx {
 25	    pub iii: IIIClient,
 26	    pub http: reqwest::Client,
 27	    aborts: Mutex<HashMap<String, AbortHandle>>,
 28	}
 29	
 30	/// One host's live registration, dropped when the admin removes it.
 31	pub struct Live {
 32	    pub host: Value,
 33	    functions: Vec<FunctionRef>,
 34	    ready: Option<Trigger>,
 35	}
 36	
 37	impl Live {
 38	    pub fn unregister(&self) {
 39	        self.functions.iter().for_each(FunctionRef::unregister);
 40	        if let Some(t) = &self.ready {
 41	            t.unregister();
 42	        }
 43	    }
 44	}
 45	
 46	impl Ctx {
 47	    pub fn new(iii: IIIClient) -> Arc<Self> {
 48	        let http = reqwest::Client::builder()
 49	            .connect_timeout(Duration::from_secs(10))
 50	            .build()
 51	            .expect("an HTTP client");
 52	        Arc::new(Self {
 53	            iii,
 54	            http,
 55	            aborts: Mutex::new(HashMap::new()),
 56	        })
 57	    }
 58	
 59	    pub async fn call(&self, function: &str, payload: Value) -> Result<Value, String> {
 60	        let request = TriggerRequest::new(function, payload).namespace(NAMESPACE);
 61	        self.iii.trigger(request).await.map_err(|e| e.to_string())
 62	    }
 63	
 64	    pub async fn kept(&self, key: &str) -> Value {
 65	        let get = json!({ "scope": WORKER, "key": key });
 66	        self.call("state::get", get).await.unwrap_or(Value::Null)
 67	    }
 68	
 69	    pub async fn keep(&self, key: &str, value: Value) -> Result<(), String> {
 70	        let set = json!({ "scope": WORKER, "key": key, "value": value });
 71	        self.call("state::set", set).await.map(|_| ())
 72	    }
 73	}
 74	
 75	fn token_key(id: &str) -> String {
 76	    format!("registration_token:{id}")
 77	}
 78	
 79	fn with_token(mut payload: Value, token: &Value) -> Value {
 80	    if token.is_string() {
 81	        payload["token"] = token.clone();
 82	    }
 83	    payload
 84	}
 85	
 86	/// Tell the router this host is a provider, keeping the token it answers
 87	/// with: the router refuses the id to anyone without it. An `open` host
 88	/// needs no key.
 89	async fn declare(ctx: &Ctx, host: &Value, open: bool) -> Result<(), String> {
 90	    let id = host["id"].as_str().unwrap_or_default();
 91	    let token = ctx.kept(&token_key(id)).await;
 92	    let declaration = json!({
 93	        "id": id,
 94	        "display_name": host["name"],
 95	        "credential_optional": open,
 96	        "defaults": { "api_url": host["api_url"], "max_tokens": wire::MAX_TOKENS },
 97	        "supports_model_listing": true,
 98	        "worker_id": WORKER,
 99	    });
100	    let answer = ctx
101	        .call(
102	            "router::provider::register",
103	            with_token(declaration, &token),
104	        )
105	        .await?;
106	    match &answer["registration_token"] {
107	        t @ Value::String(_) if *t != token => ctx.keep(&token_key(id), t.clone()).await,
108	        _ => Ok(()),
109	    }
110	}
111	
112	/// The host's key, URL and output limit, as the router resolves them.
113	async fn resolve(ctx: &Ctx, id: &str) -> Result<Value, String> {
114	    let token = ctx.kept(&token_key(id)).await;
115	    let ask = with_token(json!({ "id": id }), &token);
116	    let r = ctx.call("router::provider::resolve", ask).await?;
117	    match r["credential_error"].as_str() {
118	        Some(why) => Err(why.into()),
119	        None => Ok(r),
120	    }
121	}
122	
123	fn authorized(request: reqwest::RequestBuilder, resolved: &Value) -> reqwest::RequestBuilder {
124	    match resolved["credential"]["key"].as_str() {
125	        Some(key) => request.bearer_auth(key),
126	        None => request,
127	    }
128	}
129	
130	/// Read the host's models and give them to the router's catalog.
131	async fn refresh(ctx: &Ctx, id: &str) -> Result<usize, String> {
132	    let resolved = resolve(ctx, id).await?;
133	    let url = wire::models_url(resolved["api_url"].as_str().unwrap_or_default());
134	    let response = authorized(ctx.http.get(url), &resolved)
135	        .send()
136	        .await
137	        .map_err(|e| e.to_string())?;
138	    let listing: Value = response.json().await.map_err(|e| e.to_string())?;
139	    let max = resolved["max_tokens"].as_u64().unwrap_or(wire::MAX_TOKENS);
140	    let models = wire::catalog(id, &listing, max);
141	    let count = models.len();
142	    let token = ctx.kept(&token_key(id)).await;
143	    let reconcile = with_token(json!({ "provider": id, "models": models }), &token);
144	    ctx.call("router::models::reconcile", reconcile).await?;
145	    Ok(count)
146	}
147	
148	async fn declare_and_refresh(ctx: Arc<Ctx>, host: Value) {
149	    let id = host["id"].as_str().unwrap_or_default().to_string();
150	    let mut delay = Duration::from_millis(500);
151	    while let Err(e) = declare(&ctx, &host, true).await {
152	        eprintln!("[{WORKER}] {id}: register failed ({e}); retrying in {delay:?}");
153	        tokio::time::sleep(delay).await;
154	        delay = (delay * 2).min(Duration::from_secs(10));
155	    }
156	    match refresh(&ctx, &id).await {
157	        Ok(n) => println!("[{WORKER}] {id}: {n} models"),
158	        Err(e) => eprintln!("[{WORKER}] {id}: no models ({e})"),
159	    }
160	}
161	
162	/// A removed host. The router has no call to drop a provider, so the host
163	/// stays listed, but it offers no models and is not ready without a key.
164	pub async fn retire(ctx: Arc<Ctx>, host: Value) {
165	    let id = host["id"].as_str().unwrap_or_default();
166	    let token = ctx.kept(&token_key(id)).await;
167	    let empty = with_token(json!({ "provider": id, "models": [] }), &token);
168	    let done = match declare(&ctx, &host, false).await {
169	        Ok(()) => ctx
170	            .call("router::models::reconcile", empty)
171	            .await
172	            .map(|_| ()),
173	        Err(e) => Err(e),
174	    };
175	    if let Err(e) = done {
176	        eprintln!("[{WORKER}] {id}: not retired ({e})");
177	    }
178	}
179	
180	/// Send the host's whole answer, pinging the router while it waits.
181	async fn ask(
182	    ctx: &Ctx,
183	    turn: &wire::Turn<'_>,
184	    input: &Value,
185	    writer: &ChannelWriter,
186	) -> Result<Value, (String, String)> {
187	    let permanent = |e: String| ("permanent".to_string(), e);
188	    let resolved = resolve(ctx, turn.host)
189	        .await
190	        .map_err(|e| ("auth_expired".into(), e))?;
191	    let url = resolved["api_url"].as_str().unwrap_or_default();
192	    let max = resolved["max_tokens"].as_u64().unwrap_or(wire::MAX_TOKENS);
193	    let body = wire::request(turn, input, max);
194	    let send = authorized(ctx.http.post(url), &resolved).json(&body).send();
195	    tokio::pin!(send);
196	    let mut ping = tokio::time::interval(PING);
197	    ping.tick().await;
198	    let response = loop {
199	        tokio::select! {
200	            r = &mut send => break r.map_err(|e| ("transient".to_string(), e.to_string()))?,
201	            _ = ping.tick() => { let _ = writer.send_message(r#"{"type":"ping"}"#).await; }
202	        }
203	    };
204	    let status = response.status();
205	    let text = response
206	        .text()
207	        .await
208	        .map_err(|e| permanent(e.to_string()))?;
209	    if !status.is_success() {
210	        return Err((
211	            wire::error_kind(status.as_u16()).into(),
212	            format!("{status}: {text}"),
213	        ));
214	    }
215	    serde_json::from_str(&text).map_err(|e| permanent(e.to_string()))
216	}
217	
218	async fn turn(ctx: Arc<Ctx>, id: String, input: Value) -> Result<(), String> {
219	    let channel: StreamChannelRef =
220	        serde_json::from_value(input["writer_ref"].clone()).map_err(|e| e.to_string())?;
221	    let writer = ChannelWriter::new(ctx.iii.address(), &channel);
222	    let model = input["model"].as_str().unwrap_or_default();
223	    let turn = wire::Turn { host: &id, model };
224	    let frames = match ask(&ctx, &turn, &input, &writer).await {
225	        Ok(answer) => turn.frames(&answer),
226	        Err((kind, why)) => turn.failure(&kind, &why),
227	    };
228	    for frame in frames {
229	        writer
230	            .send_message(&frame.to_string())
231	            .await
232	            .map_err(|e| e.to_string())?;
233	    }
234	    writer.close().await.map_err(|e| e.to_string())
235	}
236	
237	/// `provider::<id>::stream`: the turn runs as a task `abort` can stop.
238	async fn stream(ctx: Arc<Ctx>, id: String, input: Value) -> Result<Value, Error> {
239	    let key = input["resolution_key"]
240	        .as_str()
241	        .unwrap_or_default()
242	        .to_string();
243	    let task = tokio::spawn(turn(ctx.clone(), id, input));
244	    ctx.aborts
245	        .lock()
246	        .unwrap()
247	        .insert(key.clone(), task.abort_handle());
248	    let ended = task.await;
249	    ctx.aborts.lock().unwrap().remove(&key);
250	    match ended {
251	        Ok(Err(e)) => Err(Error::Handler(e)),
252	        _ => Ok(json!({ "ok": true })),
253	    }
254	}
255	
256	fn abort(ctx: &Ctx, input: &Value) -> Value {
257	    let key = input["request_id"].as_str().unwrap_or_default();
258	    let handle = ctx.aborts.lock().unwrap().remove(key);
259	    handle.iter().for_each(AbortHandle::abort);
260	    json!({ "aborted": handle.is_some() })
261	}
262	
263	/// Register host `host`'s four functions and declare it to the router.
264	// `router::ready` is a trigger type, and `observe` only watches functions, so
265	// this binds it the deprecated way, as the server's engine does.
266	#[allow(deprecated)]
267	pub fn register(ctx: &Arc<Ctx>, host: &Value) -> Live {
268	    let id = host["id"].as_str().unwrap_or_default().to_string();
269	    let function = |name: &str| format!("provider::{id}::{name}");
270	    let internal = json!({ "internal": true });
271	    let (c, i) = (ctx.clone(), id.clone());
272	    let on_stream =
273	        RegisterFunction::new_async(move |input: Value| stream(c.clone(), i.clone(), input));
274	    let c = ctx.clone();
275	    let on_abort = RegisterFunction::new_async(move |input: Value| {
276	        let answer = abort(&c, &input);
277	        async move { Ok::<_, Error>(answer) }
278	    });
279	    let (c, i) = (ctx.clone(), id.clone());
280	    let on_refresh = RegisterFunction::new_async(move |_: Value| {
281	        let (c, i) = (c.clone(), i.clone());
282	        async move {
283	            let count = refresh(&c, &i).await.map_err(Error::Handler)?;
284	            Ok::<_, Error>(json!({ "ok": true, "count": count }))
285	        }
286	    });
287	    let (c, h) = (ctx.clone(), host.clone());
288	    let on_ready = RegisterFunction::new_async(move |_: Value| {
289	        tokio::spawn(declare_and_refresh(c.clone(), h.clone()));
290	        async { Ok::<_, Error>(json!({ "ok": true })) }
291	    });
292	    let functions = vec![
293	        ctx.iii.register_function(function("stream"), on_stream),
294	        ctx.iii
295	            .register_function(function("abort"), on_abort.metadata(internal.clone())),
296	        ctx.iii
297	            .register_function(function("refresh_models"), on_refresh),
298	        ctx.iii
299	            .register_function(function("on_router_ready"), on_ready.metadata(internal)),
300	    ];
301	    let bind = RegisterTriggerInput::new("router::ready", function("on_router_ready"), json!({}));
302	    let ready = ctx.iii.register_trigger(bind).ok();
303	    tokio::spawn(declare_and_refresh(ctx.clone(), host.clone()));
304	    Live {
305	        host: host.clone(),
306	        functions,
307	        ready,
308	    }
309	}

