  1	//! Calls to a Bastion server (PLAN.md D28): each command goes over HTTP by
  2	//! the route table in `bastion-protocol`, with the server's bearer token.
  3	
  4	use bastion_protocol::Server;
  5	use bastion_protocol::routes::{self, Body};
  6	use serde_json::{Map, Value};
  7	
  8	/// One HTTP client for every call, so connections are kept.
  9	pub fn http() -> reqwest::Client {
 10	    reqwest::Client::new()
 11	}
 12	
 13	/// One command for a server and its arguments.
 14	pub struct Ask {
 15	    pub cmd: &'static str,
 16	    pub args: Value,
 17	}
 18	
 19	impl Ask {
 20	    /// A command with no arguments.
 21	    pub fn bare(cmd: &'static str) -> Self {
 22	        Ask {
 23	            cmd,
 24	            args: Value::Null,
 25	        }
 26	    }
 27	}
 28	
 29	/// Send `ask` to `server`, and return its answer, or the server's refusal
 30	/// as text.
 31	pub async fn call(http: reqwest::Client, server: Server, ask: Ask) -> Result<Value, String> {
 32	    let Ask { cmd, args } = ask;
 33	    let (method, path, body) =
 34	        routes::route(cmd).ok_or_else(|| format!("{cmd} is not a server command"))?;
 35	    let mut args = match args {
 36	        Value::Object(map) => map,
 37	        _ => Map::new(),
