 63	/// A success's value, or a refusal's text: `{ "error": text }`, or the
 64	/// typed error as it is.
 65	fn answer(ok: bool, text: &str) -> Result<Value, String> {
 66	    let value: Value = serde_json::from_str(text).unwrap_or(Value::Null);
 67	    if ok {
 68	        return Ok(value);
 69	    }
 70	    match value.get("error").cloned().unwrap_or(value) {
 71	        Value::String(why) => Err(why),
 72	        other => Err(other.to_string()),
 73	    }
 74	}
 75	
 76	/// Put each `{name}` argument into the path, and take it out of the args.
 77	fn fill(template: &str, args: &mut Map<String, Value>) -> String {
 78	    let mut path = template.to_string();
 79	    while let Some(start) = path.find('{') {
 80	        let end = start + path[start..].find('}').unwrap_or(0);
 81	        let name = path[start + 1..end].to_string();
 82	        let value = match args.remove(&name) {
 83	            Some(Value::String(s)) => s,
 84	            Some(other) => other.to_string(),
 85	            None => String::new(),
 86	        };
 87	        path.replace_range(start..=end, &encode(&value));
 88	    }
 89	    path
 90	}
