 92	/// A path segment, percent-encoded.
 93	fn encode(segment: &str) -> String {
 94	    let kept = |b: u8| b.is_ascii_alphanumeric() || b"-._~".contains(&b);
 95	    segment
 96	        .bytes()
 97	        .map(|b| {
 98	            if kept(b) {
 99	                (b as char).to_string()
100	            } else {
101	                format!("%{b:02X}")
102	            }
103	        })
104	        .collect()
105	}
