  1	//! Each Bastion server's pushes (PLAN.md D29): one `GET /events` stream per
  2	//! server, read again with `Last-Event-ID` after it drops.
  3	
  4	use std::time::Duration;
  5	
  6	use bastion_protocol::{Change, Server};
  7	use futures_util::{SinkExt, Stream, StreamExt};
  8	use iced::Subscription;
  9	
 10	/// What a server's stream says.
 11	#[derive(Clone, Debug)]
 12	pub enum Feed {
 13	    /// The stream is open: the server answers.
 14	    Up,
 15	    /// The stream dropped: the server cannot be reached until it is back.
 16	    Down,
 17	    Change(Change),
 18	    /// Changes were missed: read everything again.
 19	    Resync,
 20	}
 21	
 22	/// The pushes of every server in `servers`, each tagged with its name.
 23	pub fn follow(servers: &[Server]) -> Subscription<(String, Feed)> {
 24	    let each = servers.iter().map(|s| {
 25	        let key = (s.name.clone(), s.url.clone(), s.token.clone());
 26	        Subscription::run_with(key, stream)
 27	    });
 28	    Subscription::batch(each)
 29	}
 30	
 31	type Key = (String, String, String);
 32	
 33	fn stream(key: &Key) -> impl Stream<Item = (String, Feed)> + use<> {
 34	    let (name, url, token) = key.clone();
 35	    let server = Server { name, url, token };
 36	    iced::stream::channel(64, async move |mut out| {
 37	        let http = reqwest::Client::new();
 38	        let mut last = None;
 39	        loop {
 40	            let _ = read(&http, &server, &mut last, &mut out).await;
 41	            let _ = out.send((server.name.clone(), Feed::Down)).await;
 42	            tokio::time::sleep(Duration::from_secs(1)).await;
 43	        }
 44	    })
 45	}
 46	
 47	type Out = iced::futures::channel::mpsc::Sender<(String, Feed)>;
 48	
 49	/// Read one connection until it ends.
 50	async fn read(
 51	    http: &reqwest::Client,
 52	    server: &Server,
 53	    last: &mut Option<String>,
 54	    out: &mut Out,
 55	) -> Result<(), String> {
 56	    let url = format!("{}/events", server.url.trim_end_matches('/'));
 57	    let mut request = http.get(url).bearer_auth(&server.token);
 58	    if let Some(id) = last.as_deref() {
 59	        request = request.header("Last-Event-ID", id);
 60	    }
 61	    let response = request.send().await.map_err(|e| e.to_string())?;
 62	    if !response.status().is_success() {
 63	        return Err(format!("events: status {}", response.status()));
 64	    }
 65	    let send = |feed| (server.name.clone(), feed);
 66	    let _ = out.send(send(Feed::Up)).await;
 67	    // A reconnect may have missed changes the server did not replay.
 68	    if last.is_some() {
 69	        let _ = out.send(send(Feed::Resync)).await;
 70	    }
 71	    let mut body = response.bytes_stream();
 72	    let mut buffer = String::new();
 73	    while let Some(chunk) = body.next().await {
 74	        buffer.push_str(&String::from_utf8_lossy(&chunk.map_err(|e| e.to_string())?));
 75	        while let Some(end) = buffer.find("\n\n") {
 76	            let block: String = buffer.drain(..end + 2).collect();
 77	            for feed in parse(&block, last) {
 78	                let _ = out.send(send(feed)).await;
 79	            }
 80	        }
 81	    }
 82	    Ok(())
 83	}
 84	
 85	/// One server-sent event: an id and a change, or a request to read again.
 86	fn parse(block: &str, last: &mut Option<String>) -> Vec<Feed> {
 87	    let mut feeds = Vec::new();
 88	    for line in block.lines() {
 89	        if let Some(id) = line.strip_prefix("id: ") {
 90	            *last = Some(id.to_string());
 91	        } else if line == "event: resync" {
 92	            feeds.push(Feed::Resync);
 93	        } else if let Some(change) = line
 94	            .strip_prefix("data: ")
 95	            .and_then(|d| serde_json::from_str(d).ok())
 96	        {
 97	            feeds.push(Feed::Change(change));
 98	        }
 99	    }
100	    feeds
101	}
102	
103	#[cfg(test)]
104	mod tests {
105	    use super::*;
106	
107	    #[test]
108	    fn an_event_keeps_its_id_and_a_resync_asks_to_read_again() {
109	        let mut last = None;
110	        let feeds = parse(
111	            "id: 7\ndata: {\"kind\":\"job\",\"id\":\"j1\"}\n\n",
112	            &mut last,
113	        );
114	        assert_eq!(last.as_deref(), Some("7"));
115	        assert!(matches!(&feeds[..], [Feed::Change(Change::Job { id })] if id == "j1"));
116	        assert!(matches!(
117	            &parse("event: resync\ndata: {}\n\n", &mut last)[..],
118	            [Feed::Resync]
119	        ));
120	        assert!(parse(": keep-alive\n\n", &mut last).is_empty());
121	    }
122	}
  1	//! The Bastion servers this app knows (D30): `local`, which the app starts,
  2	//! and the ones the owner added. A server's name and URL live in
  3	//! `servers.toml`; its token lives in the Keychain.
  4	
  5	use std::path::{Path, PathBuf};
  6	
  7	use bastion_protocol::{LOCAL, Server};
  8	use serde::{Deserialize, Serialize};
  9	
 10	pub const FILE_NAME: &str = "servers.toml";
 11	/// The Keychain service each server's token is kept under.
 12	const SERVICE: &str = "dev.tacoda.bastion.server";
 13	
 14	/// Where the tokens are kept.
 15	pub trait Vault: Send + Sync {
 16	    fn get(&self, name: &str) -> Result<String, String>;
 17	    fn set(&self, name: &str, token: &str) -> Result<(), String>;
 18	    fn remove(&self, name: &str) -> Result<(), String>;
 19	}
 20	
 21	/// The macOS Keychain.
 22	pub struct Keychain;
 23	
 24	fn entry(name: &str) -> Result<keyring::Entry, String> {
 25	    keyring::Entry::new(SERVICE, name).map_err(|e| e.to_string())
 26	}
 27	
 28	impl Vault for Keychain {
 29	    fn get(&self, name: &str) -> Result<String, String> {
 30	        entry(name)?
 31	            .get_password()
 32	            .map_err(|e| format!("{name}'s token: {e}"))
 33	    }
 34	
 35	    fn set(&self, name: &str, token: &str) -> Result<(), String> {
 36	        entry(name)?.set_password(token).map_err(|e| e.to_string())
 37	    }
 38	
 39	    fn remove(&self, name: &str) -> Result<(), String> {
 40	        match entry(name)?.delete_credential() {
 41	            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
 42	            Err(e) => Err(e.to_string()),
 43	        }
 44	    }
 45	}
 46	
 47	/// One added server as the file keeps it, without its token.
 48	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
 49	struct Added {
 50	    name: String,
 51	    url: String,
 52	}
 53	
 54	#[derive(Debug, Default, Serialize, Deserialize)]
 55	struct File {
 56	    #[serde(default)]
 57	    server: Vec<Added>,
 58	}
 59	
 60	pub struct Servers {
 61	    path: PathBuf,
 62	    local: Server,
 63	    vault: Box<dyn Vault>,
 64	}
 65	
 66	impl Servers {
 67	    pub fn new(path: PathBuf, local: Server, vault: Box<dyn Vault>) -> Self {
 68	        Servers { path, local, vault }
 69	    }
 70	
 71	    fn read(&self) -> Result<File, String> {
 72	        match std::fs::read_to_string(&self.path) {
 73	            Ok(text) => toml::from_str(&text).map_err(|e| format!("{}: {e}", self.path.display())),
 74	            Err(_) => Ok(File::default()),
 75	        }
 76	    }
 77	
 78	    fn write(&self, file: &File) -> Result<(), String> {
 79	        let text = toml::to_string(file).map_err(|e| e.to_string())?;
 80	        write_file(&self.path, &text)
 81	    }
 82	
 83	    /// `local` first, then the added servers in the order they were added.
 84	    pub fn all(&self) -> Result<Vec<Server>, String> {
 85	        let mut all = vec![self.local.clone()];
 86	        for a in self.read()?.server {
 87	            let token = self.vault.get(&a.name)?;
 88	            all.push(Server {
 89	                name: a.name,
 90	                url: a.url,
 91	                token,
 92	            });
 93	        }
 94	        Ok(all)
 95	    }
 96	
 97	    pub fn add(&self, server: Server) -> Result<(), String> {
 98	        let name = server.name.trim();
 99	        let url = server.url.trim().trim_end_matches('/');
100	        if name.is_empty() || server.token.trim().is_empty() {
101	            return Err("a Bastion server needs a name, a URL and a token".into());
102	        }
103	        if !(url.starts_with("http://") || url.starts_with("https://")) {
104	            return Err(format!("{url} is not an http:// or https:// URL"));
105	        }
106	        let mut file = self.read()?;
107	        if name == LOCAL || file.server.iter().any(|s| s.name == name) {
108	            return Err(format!("there is already a Bastion server named {name}"));
109	        }
110	        self.vault.set(name, server.token.trim())?;
111	        file.server.push(Added {
112	            name: name.into(),
113	            url: url.into(),
114	        });
115	        self.write(&file)
116	    }
117	
118	    pub fn remove(&self, name: &str) -> Result<(), String> {
119	        if name == LOCAL {
120	            return Err("local is the server this app runs; it cannot be removed".into());
121	        }
122	        let mut file = self.read()?;
123	        file.server.retain(|s| s.name != name);
124	        self.write(&file)?;
125	        self.vault.remove(name)
126	    }
127	}
128	
129	fn write_file(path: &Path, text: &str) -> Result<(), String> {
130	    if let Some(dir) = path.parent() {
131	        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
132	    }
133	    std::fs::write(path, text).map_err(|e| format!("{}: {e}", path.display()))
134	}
135	
136	#[cfg(test)]
137	mod tests {
138	    use std::collections::HashMap;
139	    use std::sync::Mutex;
140	
141	    use super::*;
142	
143	    #[derive(Default)]
144	    struct Memory(Mutex<HashMap<String, String>>);
145	
146	    impl Vault for Memory {
147	        fn get(&self, name: &str) -> Result<String, String> {
148	            self.0
149	                .lock()
150	                .unwrap()
151	                .get(name)
152	                .cloned()
153	                .ok_or("none".into())
154	        }
155	        fn set(&self, name: &str, token: &str) -> Result<(), String> {
156	            self.0.lock().unwrap().insert(name.into(), token.into());
157	            Ok(())
158	        }
159	        fn remove(&self, name: &str) -> Result<(), String> {
160	            self.0.lock().unwrap().remove(name);
161	            Ok(())
162	        }
163	    }
164	
165	    fn server(name: &str, url: &str) -> Server {
166	        Server {
167	            name: name.into(),
168	            url: url.into(),
169	            token: format!("{name}-token"),
170	        }
171	    }
172	
173	    fn servers(dir: &Path) -> Servers {
174	        let local = server(LOCAL, "http://127.0.0.1:49190");
175	        Servers::new(dir.join(FILE_NAME), local, Box::new(Memory::default()))
176	    }
177	
178	    fn scratch(tag: &str) -> PathBuf {
179	        let dir =
180	            std::env::temp_dir().join(format!("bastion-servers-{tag}-{}", std::process::id()));
181	        let _ = std::fs::remove_dir_all(&dir);
182	        dir
183	    }
184	
185	    #[test]
186	    fn local_comes_first_and_an_added_server_keeps_its_token_out_of_the_file() {
187	        let dir = scratch("add");
188	        let s = servers(&dir);
189	        s.add(server("box", "https://box.example/")).unwrap();
190	        let all = s.all().unwrap();
191	        let names: Vec<&str> = all.iter().map(|s| s.name.as_str()).collect();
192	        assert_eq!(names, [LOCAL, "box"]);
193	        assert_eq!(
194	            (all[1].url.as_str(), all[1].token.as_str()),
195	            ("https://box.example", "box-token")
196	        );
197	        let file = std::fs::read_to_string(dir.join(FILE_NAME)).unwrap();
198	        assert!(!file.contains("box-token"), "{file}");
199	    }
200	
201	    #[test]
202	    fn a_name_taken_a_bad_url_or_removing_local_is_refused() {
203	        let s = servers(&scratch("refuse"));
204	        s.add(server("box", "https://box.example")).unwrap();
205	        assert!(s.add(server("box", "https://other.example")).is_err());
206	        assert!(s.add(server(LOCAL, "https://other.example")).is_err());
207	        assert!(s.add(server("ftp", "ftp://box.example")).is_err());
208	        assert!(s.remove(LOCAL).is_err());
209	        s.remove("box").unwrap();
210	        assert_eq!(s.all().unwrap().len(), 1);
211	    }
212	}

