 1	//! What the window does before its first page: start or attach to the
 2	//! `local` Bastion server, and read the servers the owner added. The files
 3	//! sit where the Tauri app kept them, so both clients share them until G4.
 4	
 5	use std::path::{Path, PathBuf};
 6	
 7	use bastion_protocol::Server;
 8	
 9	use crate::local;
10	use crate::profile::{self, Profiles};
11	use crate::servers::{self, Keychain, Servers};
12	
13	/// The checkout this build came from, which holds `worker-compose.yaml`.
14	// ponytail: a build-time path; packaging the stack replaces it (PLAN.md A13).
15	const CHECKOUT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");
16	const IDENTIFIER: &str = "dev.tacoda.bastion";
17	
18	fn home() -> PathBuf {
19	    PathBuf::from(std::env::var_os("HOME").unwrap_or_default())
20	}
21	
22	/// Where the app's files live: Application Support on macOS, the XDG
23	/// directories elsewhere, as Tauri put them.
24	fn dir(xdg: &str, fallback: &str) -> PathBuf {
25	    if cfg!(target_os = "macos") {
26	        return home().join("Library/Application Support").join(IDENTIFIER);
27	    }
28	    let base = std::env::var_os(xdg).map_or_else(|| home().join(fallback), PathBuf::from);
29	    base.join(IDENTIFIER)
30	}
31	
32	pub fn config_dir() -> PathBuf {
33	    dir("XDG_CONFIG_HOME", ".config")
34	}
35	
36	fn data_dir() -> PathBuf {
37	    dir("XDG_DATA_HOME", ".local/share")
38	}
39	
40	/// The servers this app knows, around the `local` one.
41	pub fn servers(local: Server) -> Servers {
42	    Servers::new(
43	        config_dir().join(servers::FILE_NAME),
44	        local,
45	        Box::new(Keychain),
46	    )
47	}
48	
49	/// Start or attach to `local`. Blocks until it answers, so it runs off the
50	/// window's thread.
51	pub fn start() -> Result<Server, String> {
52	    let checkout = Path::new(CHECKOUT)
53	        .canonicalize()
54	        .map_err(|e| e.to_string())?;
55	    let profiles = Profiles::load_or_create(&config_dir().join(profile::FILE_NAME), checkout)?;
56	    local::start(profiles.active(), &data_dir().join("server"))
57	}
58	
59	/// Every server, `local` first. The added servers' tokens come from the
60	/// Keychain, which can take seconds, so the window shows `local` first.
61	pub fn every(local: Server) -> Result<Vec<Server>, String> {
62	    servers(local).all()
63	}
 1	//! The `local` Bastion server (D30): a `bastion-server` on this machine, started by the
 2	//! app, or the one already running. It outlives the app, so jobs go on.
 3	
 4	use std::fs::File;
 5	use std::net::TcpStream;
 6	use std::path::{Path, PathBuf};
 7	use std::process::{Command, Stdio};
 8	use std::time::{Duration, Instant};
 9	
10	use bastion_protocol::{LOCAL, Server};
11	
12	use crate::profile::Profile;
13	
14	/// The port the local server listens on.
15	pub const PORT: u16 = 49190;
16	/// How long a start may take before the app gives up on it.
17	const START_WAIT: Duration = Duration::from_secs(20);
18	
19	/// The server binary this build runs.
20	// ponytail: the dev build's path; A13 ships it beside the app.
21	const BINARY: &str = concat!(
22	    env!("CARGO_MANIFEST_DIR"),
23	    "/../../target/debug/bastion-server"
24	);
25	
26	/// Attach to the local server, starting it first if nothing listens on its
27	/// port. `data` holds its token and its log.
28	pub fn start(profile: &Profile, data: &Path) -> Result<Server, String> {
29	    if !listening() {
30	        spawn(profile, data)?;
31	    }
32	    let token = data.join("token");
33	    let since = Instant::now();
34	    while !(listening() && token.exists()) {
35	        if since.elapsed() > START_WAIT {
36	            return Err(format!(
37	                "bastion-server did not start within {}s; see {}",
38	                START_WAIT.as_secs(),
39	                data.join("server.log").display()
40	            ));
41	        }
42	        std::thread::sleep(Duration::from_millis(200));
43	    }
44	    Ok(Server {
45	        name: LOCAL.into(),
46	        url: format!("http://127.0.0.1:{PORT}"),
47	        token: std::fs::read_to_string(&token)
48	            .map_err(|e| format!("{}: {e}", token.display()))?
49	            .trim()
50	            .into(),
51	    })
52	}
53	
54	fn listening() -> bool {
55	    TcpStream::connect(("127.0.0.1", PORT)).is_ok()
56	}
57	
58	/// Start the server in its own process group, so quitting the app leaves it running.
59	fn spawn(profile: &Profile, data: &Path) -> Result<(), String> {
60	    std::fs::create_dir_all(data).map_err(|e| format!("{}: {e}", data.display()))?;
61	    let log = File::create(data.join("server.log")).map_err(|e| e.to_string())?;
62	    let mut command = Command::new(PathBuf::from(BINARY));
63	    command
64	        .args(["--checkout", &profile.checkout.display().to_string()])
65	        .args(["--data", &data.display().to_string()])
66	        .args(["--port", &PORT.to_string()])
67	        .args(["--engine", &profile.engine_url])
68	        .current_dir(&profile.checkout)
69	        .stdin(Stdio::null())
70	        .stdout(log.try_clone().map_err(|e| e.to_string())?)
71	        .stderr(log);
72	    #[cfg(unix)]
73	    std::os::unix::process::CommandExt::process_group(&mut command, 0);
74	    command
75	        .spawn()
76	        .map(|_| ())
77	        .map_err(|e| format!("{BINARY}: {e}"))
78	}

