            | Message::NewRequest(_)
            | Message::Job(_)
            | Message::Govern(_)
            | Message::Engine(_)
            | Message::Evals(_)
            | Message::Settings(_)
            | Message::Workflows(_)) => {
                let ctx = self.ctx();
                return self.page.update(page, &ctx);
            }
