     1	//! A decision on the step a job waits on goes in the audit log (D33, O2): a
     2	//! person's with their name, and a dark step's as its dial's.
     3	
     4	use std::sync::Arc;
     5	
     6	use bastion_core::{Event, Job, Stage};
     7	
     8	use super::Factory;
     9	use crate::store::name;
    10	
    11	/// How the audit log words a person's decision on the step `job` waited on.
    12	fn decision(job: &Job, event: &Event, by: &str) -> String {
    13	    let verdict = match (event, &job.question) {
    14	        (Event::Commented { text }, Some(_)) => format!("answered by {by}: {text}"),
    15	        (Event::Commented { text }, None) => format!("sent back by {by}: {text}"),
    16	        _ => format!("approved by {by}"),
    17	    };
    18	    format!("{}: {verdict}", name(job.stage))
    19	}
    20	
    21	impl Factory {
    22	    /// Apply a person's decision on the step a job waits on, and note it in
    23	    /// the audit log with their name when it moved the job (D33).
    24	    pub async fn decide(self: &Arc<Self>, id: &str, event: Event, by: &str) -> Result<(), String> {
    25	        let before = self.store.load(id).await?;
    26	        self.apply(id, event.clone()).await?;
    27	        if self.store.load(id).await?.rev == before.rev {
    28	            return Ok(());
    29	        }
    30	        self.note_decision(id, decision(&before.job, &event, by));
    31	        Ok(())
    32	    }
    33	
    34	    /// Note that `stage`'s dark dial let job `id` go on.
    35	    pub(super) fn dark_decided(&self, id: &str, stage: Stage) {
    36	        self.note_decision(id, format!("{}: approved by its dark dial", name(stage)));
    37	    }
    38	
    39	    /// Note a decision on job `id` in the audit log.
    40	    fn note_decision(&self, id: &str, detail: String) {
    41	        if let Ok(log) = self.gate.audit() {
    42	            log.note(bastion_core::audit::Record {
    43	                kind: "decide".into(),
    44	                subject: id.into(),
    45	                detail,
    46	            });
    47	        }
    48	    }
    49	}
